# -*- coding: utf-8 -*-
"""Devocional diário do Meu Púlpito, parte 5 de 5 (dias 293-365, 73 devocionais).

Versículos-base apenas de Romanos a Apocalipse (livros 44-65).
Gera tools/conteudo/devocional-5.json depois de validar tudo (ver LEIA-ME.md).
Uso: python3 tools/conteudo/devocional-5.py
"""
import json, os, re, sys

AQUI = os.path.dirname(os.path.abspath(__file__))
RAIZ = os.path.normpath(os.path.join(AQUI, "..", ".."))
SAIDA = os.path.join(AQUI, "devocional-5.json")
PRIMEIRO_DIA, ULTIMO_DIA = 293, 365

D = []


def E(v, te, tp, re_, rp, ae, ap, oe, op):
    D.append({"t": [te, tp], "v": v, "r": [re_, rp], "a": [ae, ap], "o": [oe, op]})

# --- Días 293-310 ---
E("44.3.23-24", "Justificados por pura gracia", "Justificados pela pura graça",
"Pablo coloca a toda la humanidad en el mismo lugar: «todos pecaron». Nadie queda por encima de los demás, ni el más religioso ni el más correcto. Pero enseguida llega la mejor noticia: somos «justificados gratuitamente por su gracia». Justificar es declarar justo. Dios no rebaja su santidad ni ignora el pecado; lo resuelve en la cruz, por la redención que es en Cristo Jesús. Usted no necesita ganar el perdón ni pagarlo en cuotas con buenas obras. El precio ya fue pagado. Hoy puede descansar en esta verdad: su posición delante de Dios no depende de cómo le fue esta semana, sino de lo que Cristo hizo una vez y para siempre. Esa gracia no le vuelve descuidado; le vuelve agradecido.",
"Paulo coloca toda a humanidade no mesmo lugar: «todos pecaram». Ninguém fica acima dos outros, nem o mais religioso nem o mais correto. Mas logo chega a melhor notícia: somos «justificados gratuitamente pela sua graça». Justificar é declarar justo. Deus não diminui sua santidade nem ignora o pecado; ele o resolve na cruz, por meio da redenção que há em Cristo Jesus. Você não precisa conquistar o perdão nem pagá-lo em parcelas com boas obras. O preço já foi pago. Hoje você pode descansar nesta verdade: sua posição diante de Deus não depende de como foi a sua semana, mas do que Cristo fez uma vez por todas. Essa graça não torna você descuidado; torna você agradecido.",
"Agradezca hoy a Dios en voz alta por una falta concreta que Él ya perdonó en Cristo.",
"Agradeça hoje a Deus em voz alta por uma falta concreta que ele já perdoou em Cristo.",
"Señor, reconozco que pequé y que no merezco nada. Gracias porque en Cristo me declaraste justo por pura gracia. Líbrame de confiar en mis méritos y enséñame a descansar en la obra de la cruz, viviendo cada día con un corazón agradecido. En el nombre de Jesús, amén.",
"Senhor, reconheço que pequei e que não mereço nada. Obrigado porque em Cristo me declaraste justo pela tua graça. Livra-me de confiar nos meus méritos e ensina-me a descansar na obra da cruz, vivendo cada dia com um coração agradecido. Em nome de Jesus, amém.")

E("47.5.22-23", "Un solo fruto, nueve sabores", "Um só fruto, nove sabores",
"Pablo no habla de «los frutos», sino del «fruto del Espíritu». Es una sola vida, la vida de Cristo, que se manifiesta de muchas maneras: amor, gozo, paz, paciencia, benignidad, bondad, fe, mansedumbre y templanza. Un árbol no produce fruto a fuerza de esfuerzo, sino porque está unido a la raíz y recibe su savia. Así ocurre con usted. El carácter cristiano no se fabrica con disciplina humana solamente; brota cuando el Espíritu Santo tiene libertad en el corazón. Por eso Pablo contrasta este fruto con las obras de la carne de los versículos anteriores. Si hoy nota impaciencia o dureza en su trato, no se desanime: acérquese más a Dios. El fruto crece despacio, pero crece donde hay comunión.",
"Paulo não fala de «os frutos», mas do «fruto do Espírito». É uma só vida, a vida de Cristo, que se manifesta de muitas formas: amor, alegria, paz, paciência, benignidade, bondade, fidelidade, mansidão e domínio próprio. Uma árvore não produz fruto à força de esforço, mas porque está unida à raiz e recebe a sua seiva. Assim acontece com você. O caráter cristão não se fabrica apenas com disciplina humana; ele brota quando o Espírito Santo tem liberdade no coração. Por isso Paulo contrasta esse fruto com as obras da carne dos versículos anteriores. Se hoje você percebe impaciência ou dureza no seu trato, não desanime: aproxime-se mais de Deus. O fruto cresce devagar, mas cresce onde há comunhão.",
"Elija una de las nueve virtudes y pida al Espíritu que la muestre en usted en una situación concreta de hoy.",
"Escolha uma das nove virtudes e peça ao Espírito que a mostre em você numa situação concreta de hoje.",
"Espíritu Santo, reconozco que no puedo producir buen fruto por mí mismo. Toma mi carácter, mis reacciones y mis palabras. Haz crecer en mí el amor, el gozo y la paz, y que las personas a mi alrededor vean a Cristo en mi manera de vivir. En el nombre de Jesús, amén.",
"Espírito Santo, reconheço que não consigo produzir bom fruto por mim mesmo. Toma o meu caráter, as minhas reações e as minhas palavras. Faz crescer em mim o amor, a alegria e a paz, e que as pessoas ao meu redor vejam Cristo no meu jeito de viver. Em nome de Jesus, amém.")

E("58.1.2-3", "Gozo en medio de la prueba", "Alegria no meio da prova",
"Santiago escribe algo que parece contradictorio: tener «por sumo gozo» las diversas pruebas. No nos pide disfrutar del dolor ni fingir que todo está bien. Nos invita a mirar más allá del momento, «sabiendo» algo: la prueba de la fe produce paciencia, es decir, perseverancia firme. Dios no desperdicia ninguna dificultad en la vida de sus hijos. Lo que hoy le aprieta puede estar formando en usted una fe más madura y estable, que no se derrumba con cualquier viento. El gozo cristiano no depende de las circunstancias, sino de la certeza de que Dios está obrando en ellas. Si atraviesa un tiempo difícil, pregúntese no solo «¿por qué?», sino también «¿qué está formando Dios en mí?».",
"Tiago escreve algo que parece contraditório: ter «toda alegria» nas várias provações. Ele não nos pede para gostar da dor nem fingir que está tudo bem. Ele nos convida a olhar além do momento, «sabendo» algo: a prova da fé produz perseverança. Deus não desperdiça nenhuma dificuldade na vida dos seus filhos. O que hoje aperta você pode estar formando uma fé mais madura e estável, que não desaba com qualquer vento. A alegria cristã não depende das circunstâncias, mas da certeza de que Deus está agindo nelas. Se você atravessa um tempo difícil, pergunte não apenas «por quê?», mas também «o que Deus está formando em mim?».",
"Escriba una dificultad que está viviendo y, al lado, una cualidad que Dios puede estar formando en usted a través de ella.",
"Escreva uma dificuldade que você está vivendo e, ao lado, uma qualidade que Deus pode estar formando em você por meio dela.",
"Señor, no es fácil alegrarme en la prueba, pero confío en que no me has dejado solo. Usa esta dificultad para hacer mi fe más firme y paciente. Dame gozo verdadero, que no dependa de lo que veo, sino de quién eres. En el nombre de Jesús, amén.",
"Senhor, não é fácil me alegrar na prova, mas confio que não me deixaste sozinho. Usa esta dificuldade para tornar minha fé mais firme e perseverante. Dá-me alegria verdadeira, que não dependa do que vejo, mas de quem tu és. Em nome de Jesus, amém.")

E("45.12.26-27", "Nadie sufre solo en el cuerpo", "Ninguém sofre sozinho no corpo",
"Pablo compara la iglesia con un cuerpo humano. Cuando a usted le duele un dedo, todo el cuerpo lo siente; nadie dice «eso no es asunto mío». Así debe ser entre los hermanos: «si un miembro padece, todos los miembros a una se duelen; y si un miembro es honrado, todos a una se gozan». La iglesia no es un público que asiste a un evento, sino un organismo vivo, el cuerpo de Cristo. Esto nos libra de dos males: la indiferencia ante el dolor ajeno y la envidia ante el éxito ajeno. Llorar con el que llora y alegrarse sinceramente con el que es bendecido son señales de que pertenecemos de verdad unos a otros. Usted es parte de ese cuerpo, y su presencia importa.",
"Paulo compara a igreja a um corpo humano. Quando dói um dedo seu, o corpo inteiro sente; ninguém diz «isso não é problema meu». Assim deve ser entre os irmãos: «caso um membro sofra, também os membros sofrem juntos; e caso um membro seja honrado, todos os membros se alegram juntos». A igreja não é uma plateia que assiste a um evento, mas um organismo vivo, o corpo de Cristo. Isso nos livra de dois males: a indiferença diante da dor alheia e a inveja diante do sucesso alheio. Chorar com quem chora e alegrar-se sinceramente com quem é abençoado são sinais de que pertencemos de verdade uns aos outros. Você faz parte desse corpo, e a sua presença importa.",
"Llame o escriba hoy a un hermano que está sufriendo, y felicite a otro que recibió una bendición.",
"Ligue ou escreva hoje para um irmão que está sofrendo, e parabenize outro que recebeu uma bênção.",
"Señor, gracias por ponerme en la iglesia de Cristo. Quita de mí la indiferencia y la envidia. Dame un corazón sensible para acompañar al que sufre y alegría sincera por la bendición de mis hermanos, para que vivamos como un solo cuerpo. En el nombre de Jesús, amén.",
"Senhor, obrigado por me colocar na tua igreja. Tira de mim a indiferença e a inveja. Dá-me um coração sensível para acompanhar quem sofre e alegria sincera pela bênção dos meus irmãos, para que vivamos como um só corpo. Em nome de Jesus, amém.")

E("51.4.16-17", "Siempre con el Señor", "Para sempre com o Senhor",
"Los tesalonicenses estaban tristes por los hermanos que habían muerto. Pablo no les ofrece frases vacías, sino una esperanza concreta: el mismo Señor descenderá del cielo, los muertos en Cristo resucitarán primero, y los que vivan serán arrebatados juntamente con ellos para recibir al Señor. La meta final de todo es esta: «así estaremos siempre con el Señor». La venida de Cristo no es un tema para causar miedo en el creyente, sino para consolar. Por eso el versículo siguiente dice: «consolaos los unos a los otros en estas palabras». Si usted ha despedido a un ser querido que murió en la fe, la despedida no es definitiva. Hay un reencuentro preparado, y en el centro de ese reencuentro está Jesús.",
"Os tessalonicenses estavam tristes pelos irmãos que haviam morrido. Paulo não lhes oferece frases vazias, mas uma esperança concreta: o próprio Senhor descerá do céu, os mortos em Cristo ressuscitarão primeiro, e os que estiverem vivos serão arrebatados juntamente com eles para encontrar o Senhor. A meta final de tudo é esta: «assim estaremos para sempre com o Senhor». A vinda de Cristo não é um tema para causar medo no crente, mas para consolar. Por isso o versículo seguinte diz: «consolai-vos uns aos outros com estas palavras». Se você se despediu de um ente querido que morreu na fé, a despedida não é definitiva. Há um reencontro preparado, e no centro desse reencontro está Jesus.",
"Comparta esta esperanza con alguien que está de luto, usando las mismas palabras de Pablo.",
"Compartilhe esta esperança com alguém que está de luto, usando as mesmas palavras de Paulo.",
"Señor Jesús, gracias porque vendrás otra vez y estaremos siempre contigo. Consuela a los que lloran por sus seres queridos. Mantén viva en mí esta esperanza, y que mi vida esté preparada para recibirte con gozo. En el nombre de Jesús, amén.",
"Senhor Jesus, obrigado porque virás outra vez e estaremos para sempre contigo. Consola os que choram por seus entes queridos. Mantém viva em mim esta esperança, e que minha vida esteja preparada para te receber com alegria. Em nome de Jesus, amém.")

E("48.6.10-11", "Fuertes en el poder de Dios", "Fortes no poder de Deus",
"Al final de su carta, Pablo cambia de tono: «fortaleceos en el Señor, y en la potencia de su fortaleza». No dice «sean fuertes por ustedes mismos», sino que busquen su fuerza en el Señor. Luego explica por qué: existe un enemigo real que actúa con «asechanzas», es decir, con trampas y estrategias. El creyente no lucha contra personas, sino contra fuerzas espirituales, como aclara el versículo doce. Por eso Dios no le deja desprotegido: le ofrece «toda la armadura de Dios». No es la armadura de usted, sino la que Dios provee. El objetivo es claro: «estar firmes». No siempre se trata de avanzar con estruendo; muchas veces la victoria consiste en no ceder terreno. Hoy puede mantenerse en pie porque la fuerza viene de Él.",
"No fim da sua carta, Paulo muda de tom: «fortalecei-vos no Senhor e na força do seu poder». Ele não diz «sejam fortes por vocês mesmos», mas que busquem a força no Senhor. Depois explica por quê: existe um inimigo real que age com «ciladas», isto é, com armadilhas e estratégias. O crente não luta contra pessoas, mas contra forças espirituais, como esclarece o versículo doze. Por isso Deus não deixa você desprotegido: ele oferece «toda a armadura de Deus». Não é a sua armadura, mas a que Deus providencia. O objetivo é claro: «estar firmes». Nem sempre se trata de avançar com barulho; muitas vezes a vitória consiste em não ceder terreno. Hoje você pode permanecer de pé porque a força vem dele.",
"Identifique un área donde suele ceder ante la tentación y ore específicamente por firmeza en ella.",
"Identifique uma área em que você costuma ceder à tentação e ore especificamente por firmeza nela.",
"Señor, reconozco que mis fuerzas no alcanzan. Hoy busco mi fuerza en ti. Revísteme con la armadura que me has dado, abre mis ojos ante las trampas del enemigo y ayúdame a permanecer firme. En el nombre de Jesús, amén.",
"Senhor, reconheço que minhas forças não bastam. Hoje me fortaleço no teu poder. Reveste-me com a armadura que me deste, abre meus olhos para as ciladas do inimigo e ajuda-me a permanecer firme. Em nome de Jesus, amém.")

E("44.8.26", "Cuando no sabe qué orar", "Quando você não sabe orar",
"Hay momentos en que la carga es tan grande que las palabras no salen. Usted se arrodilla y solo puede suspirar. Pablo conoce esa experiencia y nos da un consuelo precioso: «el Espíritu ayuda nuestra flaqueza». Reconoce con honestidad que muchas veces no sabemos pedir como conviene. Pero no estamos abandonados en esa debilidad. El mismo Espíritu Santo intercede por nosotros «con gemidos indecibles». Y el versículo siguiente asegura que Dios entiende esa intercesión, porque es conforme a su voluntad. Por eso nunca deje de orar por sentir que no sabe cómo hacerlo. Una oración torpe, un silencio delante de Dios o unas lágrimas sinceras no son pérdida de tiempo. El Espíritu toma su debilidad y la presenta ante el Padre.",
"Há momentos em que o peso é tão grande que as palavras não saem. Você se ajoelha e só consegue suspirar. Paulo conhece essa experiência e nos dá um consolo precioso: «o Espírito ajuda em nossas fraquezas». Ele reconhece com honestidade que muitas vezes não sabemos orar como se deve. Mas não estamos abandonados nessa fraqueza. O próprio Espírito Santo intercede por nós «com gemidos inexprimíveis». E o versículo seguinte garante que Deus entende essa intercessão, porque é segundo a sua vontade. Por isso nunca deixe de orar por sentir que não sabe como fazer. Uma oração simples, um silêncio diante de Deus ou lágrimas sinceras não são perda de tempo. O Espírito toma a sua fraqueza e a apresenta ao Pai.",
"Dedique hoy unos minutos a estar en silencio delante de Dios, confiando en que el Espíritu intercede por usted.",
"Dedique hoje alguns minutos a ficar em silêncio diante de Deus, confiando que o Espírito intercede por você.",
"Espíritu Santo, muchas veces no sé cómo orar ni qué pedir. Gracias porque me ayudas en mi debilidad e intercedes por mí. Recibe mis suspiros y mis silencios, y llévalos delante del Padre conforme a su voluntad. En el nombre de Jesús, amén.",
"Espírito Santo, muitas vezes não sei como orar nem o que pedir. Obrigado porque me ajudas na minha fraqueza e intercedes por mim. Recebe meus suspiros e meus silêncios, e leva-os diante do Pai segundo a sua vontade. Em nome de Jesus, amém.")

E("50.3.12-13", "Vestidos de misericordia", "Vestidos de misericórdia",
"Pablo usa la imagen de la ropa: «vestíos». Así como cada mañana elegimos qué ponernos, el creyente se reviste de misericordia, benignidad, humildad, mansedumbre y paciencia. Antes de pedirlo, Pablo recuerda quiénes somos: «escogidos de Dios, santos y amados». No nos vestimos así para ganar el amor de Dios, sino porque ya somos amados. Luego llega a lo práctico: soportarnos y perdonarnos los unos a los otros cuando haya quejas. La medida es alta: «de la manera que Cristo os perdonó, así también hacedlo vosotros». Usted no puede controlar cómo le tratan, pero sí puede decidir con qué se viste por dentro. Hoy, antes de salir, revístase del carácter de Cristo; será la ropa más visible que lleve.",
"Paulo usa a imagem da roupa: «revesti-vos». Assim como toda manhã escolhemos o que vestir, o crente se reveste de misericórdia, bondade, humildade, mansidão e paciência. Antes de pedir isso, Paulo lembra quem somos: «escolhidos de Deus, santos e amados». Não nos vestimos assim para ganhar o amor de Deus, mas porque já somos amados. Depois ele chega ao prático: suportar e perdoar uns aos outros quando houver queixas. A medida é alta: «como o Senhor vos perdoou, assim também fazei vós». Você não pode controlar como os outros o tratam, mas pode decidir com o que se veste por dentro. Hoje, antes de sair, revista-se do caráter de Cristo; será a roupa mais visível que você usará.",
"Antes de comenzar su día, pida a Dios que le revista de paciencia para la persona que más le cuesta tratar.",
"Antes de começar o seu dia, peça a Deus que o revista de paciência para a pessoa com quem você tem mais dificuldade.",
"Padre, gracias porque soy escogido y amado. Hoy quiero vestirme de misericordia, humildad y paciencia. Ayúdame a soportar con amor y a perdonar como Cristo me perdonó, aunque me cueste. En el nombre de Jesús, amén.",
"Pai, obrigado porque sou escolhido e amado. Hoje quero me vestir de misericórdia, humildade e paciência. Ajuda-me a suportar com amor e a perdoar como Cristo me perdoou, mesmo quando for difícil. Em nome de Jesus, amém.")

E("44.5.1", "Paz verdadera con Dios", "Paz verdadeira com Deus",
"Antes de la paz interior que tanto buscamos, existe una paz más profunda: la paz «para con Dios». Por causa del pecado, estábamos en enemistad con nuestro Creador. Pero Pablo afirma que, «justificados por la fe», esa guerra terminó. No es un cese de fuego frágil que puede romperse con el próximo error, sino una reconciliación hecha «por medio de nuestro Señor Jesucristo». Esta paz es un hecho antes que un sentimiento. Habrá días en que usted se sienta inquieto, pero su relación con Dios sigue firme porque descansa en Cristo. Los versículos siguientes hablan de entrada a la gracia y de esperanza. Todo comienza aquí: ya no hay hostilidad entre usted y Dios. Puede acercarse a Él como hijo, no como acusado.",
"Antes da paz interior que tanto buscamos, existe uma paz mais profunda: a paz «com Deus». Por causa do pecado, estávamos em inimizade com nosso Criador. Mas Paulo afirma que, «justificados pela fé», essa guerra terminou. Não é um cessar-fogo frágil que pode se romper no próximo erro, mas uma reconciliação feita «por meio do nosso Senhor Jesus Cristo». Essa paz é um fato antes de ser um sentimento. Haverá dias em que você se sentirá inquieto, mas a sua relação com Deus continua firme porque está apoiada em Cristo. Os versículos seguintes falam de acesso à graça e de esperança. Tudo começa aqui: já não há hostilidade entre você e Deus. Você pode se aproximar dele como filho, não como acusado.",
"Cuando hoy le asalte la culpa por algo ya confesado, recuerde en voz alta: «Tengo paz con Dios por medio de Cristo».",
"Quando hoje a culpa por algo já confessado o atacar, lembre em voz alta: «Tenho paz com Deus por meio de Cristo».",
"Padre, gracias porque por medio de Jesucristo ya no soy enemigo, sino hijo amado. Afirma mi corazón en esta paz cuando las emociones cambien. Enséñame a acercarme a ti con confianza y gratitud. En el nombre de Jesús, amén.",
"Pai, obrigado porque, por meio de Jesus Cristo, já não sou teu inimigo, mas teu filho. Firma o meu coração nesta paz quando as emoções mudarem. Ensina-me a me aproximar de ti com confiança e gratidão. Em nome de Jesus, amém.")

E("59.1.6-7", "Fe más preciosa que el oro", "Fé mais preciosa que ouro",
"Pedro escribe a creyentes dispersos y afligidos. Les recuerda que la tristeza de las pruebas dura «un poco de tiempo», mientras que la herencia en Cristo es eterna. Luego usa una imagen conocida: el oro se prueba con fuego para quitarle las impurezas. Si Dios cuida tanto un metal que al final perece, ¿cuánto más cuidará la fe de sus hijos, que es «mucho más preciosa»? La prueba no viene para destruir su fe, sino para mostrar que es auténtica. Y tiene un destino glorioso: ser hallada «en alabanza, gloria y honra, cuando Jesucristo fuere manifestado». Lo que usted sufre hoy con fidelidad tiene valor eterno. Dios está mirando el horno, y no permitirá que el fuego dure más de lo necesario.",
"Pedro escreve a crentes dispersos e aflitos. Ele lembra que a tristeza das provações dura «por um pouco de tempo», enquanto a herança em Cristo é eterna. Depois usa uma imagem conhecida: o ouro é provado no fogo para tirar as impurezas. Se Deus cuida tanto de um metal que no fim perece, quanto mais cuidará da fé dos seus filhos, que é «muito mais preciosa»? A prova não vem para destruir a sua fé, mas para mostrar que ela é autêntica. E ela tem um destino glorioso: ser achada «em louvor, glória e honra» na manifestação de Jesus Cristo. O que você sofre hoje com fidelidade tem valor eterno. Deus está olhando a fornalha, e não permitirá que o fogo dure mais do que o necessário.",
"Dé gracias a Dios hoy por una prueba pasada que fortaleció su fe.",
"Agradeça a Deus hoje por uma prova passada que fortaleceu a sua fé.",
"Señor, cuando pase por el fuego, recuérdame que estás a mi lado. Purifica mi fe, quita lo que no te agrada y hazme fiel hasta el día en que Cristo sea manifestado. Que mi vida sea para alabanza y gloria de Cristo. En el nombre de Jesús, amén.",
"Senhor, quando eu passar pelo fogo, lembra-me de que estás ao meu lado. Purifica a minha fé, tira o que não te agrada e torna-me fiel até o dia em que Cristo se manifestar. Que minha vida seja para teu louvor e glória. Em nome de Jesus, amém.")

E("48.4.15-16", "Crecer juntos en amor", "Crescer juntos em amor",
"Pablo describe una iglesia que madura. La clave está en «seguir la verdad en amor»: verdad sin amor hiere, y amor sin verdad engaña. Unidos a Cristo, la cabeza, crecemos «en todas las cosas». Luego presenta una imagen hermosa: todo el cuerpo bien ligado por sus junturas, donde «cada miembro conforme a su medida» contribuye al crecimiento. Nadie es espectador. Usted tiene una parte que aportar, aunque le parezca pequeña. Una palabra de ánimo, un servicio discreto, una oración constante: todo eso fortalece las junturas del cuerpo. Y la meta no es solo crecer en número, sino «edificarse en amor». Una iglesia madura no es la que nunca tiene problemas, sino la que aprende a resolverlos con verdad y con amor.",
"Paulo descreve uma igreja que amadurece. A chave está em «seguir a verdade em amor»: verdade sem amor fere, e amor sem verdade engana. Unidos a Cristo, a cabeça, crescemos «em tudo». Depois ele apresenta uma imagem bonita: todo o corpo bem ajustado por seus ligamentos, onde cada membro, conforme a sua medida, contribui para o crescimento. Ninguém é espectador. Você tem uma parte para oferecer, ainda que lhe pareça pequena. Uma palavra de ânimo, um serviço discreto, uma oração constante: tudo isso fortalece as juntas do corpo. E a meta não é apenas crescer em número, mas «edificar-se em amor». Uma igreja madura não é a que nunca tem problemas, mas a que aprende a resolvê-los com verdade e com amor.",
"Ofrezca hoy a su iglesia un servicio concreto, por sencillo que sea.",
"Ofereça hoje à sua igreja um serviço concreto, por mais simples que seja.",
"Señor Jesús, eres la cabeza de la iglesia. Ayúdame a hablar la verdad con amor y a cumplir mi parte en el cuerpo con fidelidad. Que nuestra congregación crezca unida y edificada en amor. En el nombre de Jesús, amén.",
"Senhor Jesus, tu és a cabeça da igreja. Ajuda-me a falar a verdade com amor e a cumprir a minha parte no corpo com fidelidade. Que nossa congregação cresça unida e edificada em amor. Em nome de Jesus, amém.")

E("49.3.20-21", "Ciudadanos del cielo", "Cidadãos dos céus",
"Filipos era una colonia romana y sus habitantes se sentían orgullosos de ser ciudadanos de Roma. Pablo usa esa idea para recordar a los creyentes cuál es su verdadera patria: «nuestra vivienda es en los cielos». Usted vive en esta tierra, trabaja, paga sus cuentas y cuida de su familia, pero su identidad más profunda está en otro lugar. Desde allí «esperamos al Salvador, al Señor Jesucristo». Y cuando Él venga, transformará nuestro cuerpo débil para que sea semejante a su cuerpo glorioso. Esta esperanza cambia la manera de vivir hoy. En los versículos anteriores, Pablo lamenta a quienes solo piensan en lo terrenal. El ciudadano del cielo vive aquí con responsabilidad, pero con la mirada puesta en el Rey que viene.",
"Filipos era uma colônia romana, e seus moradores se orgulhavam de ser cidadãos de Roma. Paulo usa essa ideia para lembrar aos crentes qual é a sua verdadeira pátria: «nós somos cidadãos dos céus». Você vive nesta terra, trabalha, paga suas contas e cuida da sua família, mas a sua identidade mais profunda está em outro lugar. De lá «esperamos um Salvador, o Senhor Jesus Cristo». E quando ele vier, transformará o nosso corpo frágil para que seja semelhante ao seu corpo glorioso. Essa esperança muda a maneira de viver hoje. Nos versículos anteriores, Paulo lamenta por aqueles que só pensam nas coisas terrenas. O cidadão do céu vive aqui com responsabilidade, mas com o olhar voltado para o Rei que vem.",
"Revise una decisión que debe tomar esta semana y pregúntese cómo la tomaría un ciudadano del cielo.",
"Revise uma decisão que você precisa tomar esta semana e pergunte-se como um cidadão do céu a tomaria.",
"Señor Jesús, gracias porque mi ciudadanía está en los cielos. Ayúdame a vivir en esta tierra con responsabilidad, sin apegarme a lo pasajero. Mantén mis ojos puestos en el día en que vendrás y en la gloria que nos espera. En el nombre de Jesús, amén.",
"Senhor Jesus, obrigado porque a minha cidadania está nos céus. Ajuda-me a viver nesta terra com responsabilidade, sem me apegar ao que é passageiro. Mantém meus olhos voltados para a tua vinda e para a glória que nos espera. Em nome de Jesus, amém.")

E("47.5.16", "Caminar al paso del Espíritu", "Andar no ritmo do Espírito",
"Pablo da una instrucción sencilla y profunda: «andad en el Espíritu». Andar habla de lo cotidiano, de los pasos de cada día. No se trata de experiencias aisladas en un culto, sino de una vida que se deja guiar por el Espíritu Santo en la casa, en el trabajo y en las conversaciones. Y viene con una promesa: así «no satisfaréis la concupiscencia de la carne». Muchas veces intentamos vencer el pecado solo diciendo «no». Pablo propone algo más poderoso: llenar la vida de la presencia de Dios, de modo que los deseos de la carne pierdan su fuerza. Los versículos siguientes describen esa lucha interior. Usted no la gana con fuerza de voluntad solamente, sino caminando cerca de Aquel que le da nueva vida.",
"Paulo dá uma instrução simples e profunda: «andai no Espírito». Andar fala do cotidiano, dos passos de cada dia. Não se trata de experiências isoladas num culto, mas de uma vida que se deixa guiar pelo Espírito Santo em casa, no trabalho e nas conversas. E vem com uma promessa: assim não executareis o mau desejo da carne. Muitas vezes tentamos vencer o pecado apenas dizendo «não». Paulo propõe algo mais poderoso: encher a vida da presença de Deus, de modo que os desejos da carne percam a força. Os versículos seguintes descrevem essa luta interior. Você não a vence apenas com força de vontade, mas andando perto daquele que lhe dá nova vida.",
"Haga hoy tres pausas breves, mañana, tarde y noche, para pedir dirección al Espíritu Santo.",
"Faça hoje três pausas breves, de manhã, à tarde e à noite, para pedir direção ao Espírito Santo.",
"Espíritu Santo, quiero caminar contigo hoy en cada paso. Guía mis pensamientos, mis palabras y mis decisiones. Dame victoria sobre los deseos de la carne y lléname de ti. En el nombre de Jesús, amén.",
"Espírito Santo, quero andar contigo hoje em cada passo. Guia meus pensamentos, minhas palavras e minhas decisões. Dá-me vitória sobre os desejos da carne e enche-me da tua presença. Em nome de Jesus, amém.")

E("48.2.8-9", "Salvación, un regalo", "Salvação, um presente",
"Pocas frases resumen el evangelio tan bien como esta: «por gracia sois salvos por la fe». Pablo deja claro de dónde viene la salvación: «no de vosotros, pues es don de Dios». Un regalo no se compra ni se merece; solo se recibe con gratitud. Por eso añade: «no por obras, para que nadie se gloríe». Nadie llegará al cielo diciendo «lo logré yo». Esto quita el orgullo del que se cree mejor y quita la desesperación del que se siente demasiado pecador. Todos entramos por la misma puerta. Y el versículo diez completa la idea: no somos salvos por buenas obras, pero sí para buenas obras. La gracia no termina en usted; le pone en camino para servir a otros con gratitud.",
"Poucas frases resumem o evangelho tão bem como esta: «pela graça sois salvos, por meio da fé». Paulo deixa claro de onde vem a salvação: «isto não vem de vós; é dom de Deus». Um presente não se compra nem se merece; apenas se recebe com gratidão. Por isso ele acrescenta: «não por obras, para que ninguém tenha orgulho de si mesmo». Ninguém chegará ao céu dizendo «eu consegui». Isso tira o orgulho de quem se acha melhor e tira o desespero de quem se sente pecador demais. Todos entramos pela mesma porta. E o versículo dez completa a ideia: não somos salvos por boas obras, mas para boas obras. A graça não termina em você; ela coloca você no caminho para servir aos outros com gratidão.",
"Cuente a alguien hoy, con sencillez, que su salvación es un regalo de Dios y no un mérito propio.",
"Conte a alguém hoje, com simplicidade, que a sua salvação é um presente de Deus e não um mérito próprio.",
"Padre, gracias por el regalo de la salvación que no merecía. Quita de mí todo orgullo y toda desesperanza. Ayúdame a recibir la gracia con humildad y a responder con buenas obras hechas por amor. En el nombre de Jesús, amén.",
"Pai, obrigado pelo presente da salvação que eu não merecia. Tira de mim todo orgulho e todo desespero. Ajuda-me a receber a tua graça com humildade e a responder com boas obras feitas por amor. Em nome de Jesus, amém.")

E("45.13.4-5", "El amor tiene paciencia", "O amor tem paciência",
"Este pasaje se lee mucho en las bodas, pero Pablo lo escribió a una iglesia dividida, donde algunos usaban los dones espirituales para destacarse. Por eso describe el amor con acciones concretas: es sufrido y benigno, no tiene envidia, no se envanece, no busca lo suyo, no se irrita, no guarda rencor. Es interesante que lo primero sea la paciencia. El amor verdadero se nota en cómo tratamos a quien nos cansa o nos ofende. Una forma útil de examinarse es leer el pasaje poniendo su propio nombre en lugar de la palabra amor. Seguramente descubrirá cuánto necesita de Dios. Y eso está bien: solo Cristo ha cumplido este amor perfectamente, y es Él quien quiere formarlo en usted.",
"Este trecho é muito lido em casamentos, mas Paulo o escreveu para uma igreja dividida, onde alguns usavam os dons espirituais para se destacar. Por isso ele descreve o amor com ações concretas: é paciente e bondoso, não é invejoso, não é orgulhoso, não busca os próprios interesses, não se ira, não é rancoroso. É interessante que a primeira característica seja a paciência. O amor verdadeiro aparece na forma como tratamos quem nos cansa ou nos ofende. Uma forma útil de se examinar é ler o texto colocando o seu próprio nome no lugar da palavra amor. Provavelmente você descobrirá o quanto precisa de Deus. E está tudo bem: só Cristo cumpriu esse amor perfeitamente, e é ele quem quer formá-lo em você.",
"Lea el pasaje con su nombre en lugar de «amor» y ore por la característica que más le falta.",
"Leia o trecho com o seu nome no lugar de «amor» e ore pela característica que mais lhe falta.",
"Señor, confieso que muchas veces soy impaciente y busco lo mío. Enséñame a amar como Cristo me ama: con paciencia, bondad y humildad. Llena mi corazón de amor verdadero, para que no guarde rencor. En el nombre de Jesús, amén.",
"Senhor, confesso que muitas vezes sou impaciente e busco os meus interesses. Ensina-me a amar como Cristo me ama: com paciência, bondade e humildade. Enche meu coração do teu amor, para que eu não guarde rancor. Em nome de Jesus, amém.")

E("48.6.14-15", "Verdad, justicia y paz", "Verdade, justiça e paz",
"Pablo describe las primeras piezas de la armadura. El cinturón de la verdad sostenía toda la vestimenta del soldado; sin verdad, todo lo demás se desarma. La coraza de justicia protegía el corazón; el creyente se cubre con la justicia que Cristo le da y procura vivir con rectitud. Y el calzado del evangelio de paz le permitía al soldado estar firme y moverse con rapidez. Fíjese en el mandato inicial: «estad pues firmes». La armadura no es para exhibirla, sino para resistir. Una mentira tolerada, una práctica deshonesta o un corazón sin paz dejan huecos por donde el enemigo ataca. Hoy usted puede revisar su armadura: ¿hay verdad en sus palabras, rectitud en sus caminos y disposición para llevar la paz de Cristo a otros?",
"Paulo descreve as primeiras peças da armadura. O cinturão da verdade sustentava toda a roupa do soldado; sem verdade, todo o resto se desfaz. A couraça da justiça protegia o coração; o crente se cobre com a justiça que Cristo lhe dá e procura viver com retidão. E o calçado do evangelho da paz permitia ao soldado ficar firme e mover-se com rapidez. Observe o mandamento inicial: «estai, pois, firmes». A armadura não é para exibição, mas para resistir. Uma mentira tolerada, uma prática desonesta ou um coração sem paz deixam brechas por onde o inimigo ataca. Hoje você pode examinar a sua armadura: há verdade nas suas palavras, retidão nos seus caminhos e disposição para levar a paz de Cristo aos outros?",
"Corrija hoy cualquier pequeña falta de verdad en sus palabras o en sus negocios.",
"Corrija hoje qualquer pequena falta de verdade nas suas palavras ou nos seus negócios.",
"Señor, cíñeme con la verdad, cubre mi corazón con la justicia de Cristo y prepara mis pies para llevar el evangelio de la paz. Muéstrame las brechas en mi vida y ayúdame a cerrarlas hoy. En el nombre de Jesús, amén.",
"Senhor, cinge-me com a verdade, cobre meu coração com a justiça de Cristo e prepara meus pés para levar o evangelho da paz. Mostra-me as brechas na minha vida e ajuda-me a fechá-las hoje. Em nome de Jesus, amém.")

E("44.12.12", "Esperanza, paciencia y oración", "Esperança, paciência e oração",
"En medio de una lista de consejos prácticos, Pablo une tres actitudes que se sostienen mutuamente: «gozosos en la esperanza; sufridos en la tribulación; constantes en la oración». La esperanza mira hacia adelante, a lo que Dios prometió, y por eso produce gozo aun cuando el presente es duro. La paciencia permite soportar la tribulación sin abandonar la fe. Y la oración constante es el canal que alimenta ambas cosas. Si una de ellas falla, las otras se debilitan. Quien deja de orar pierde la esperanza con facilidad, y quien pierde la esperanza se vuelve impaciente. Hoy usted puede revisar estas tres áreas. No se trata de sentir siempre alegría, sino de mantener la mirada en Dios y la rodilla en tierra.",
"No meio de uma lista de conselhos práticos, Paulo une três atitudes que se sustentam mutuamente: «alegrai-vos na esperança, sede pacientes na aflição, perseverai na oração». A esperança olha para frente, para o que Deus prometeu, e por isso produz alegria mesmo quando o presente é difícil. A paciência permite suportar a aflição sem abandonar a fé. E a oração constante é o canal que alimenta as duas coisas. Se uma delas falha, as outras se enfraquecem. Quem deixa de orar perde a esperança com facilidade, e quem perde a esperança fica impaciente. Hoje você pode examinar essas três áreas. Não se trata de sentir sempre alegria, mas de manter o olhar em Deus e os joelhos no chão.",
"Fije un horario diario de oración para esta semana y cúmplalo, aunque sea breve.",
"Defina um horário diário de oração para esta semana e cumpra-o, ainda que seja breve.",
"Señor, lléname de gozo en la esperanza que me has dado. Dame paciencia en las tribulaciones y constancia en la oración. No permitas que me canse de buscarte, aun cuando las respuestas tarden. En el nombre de Jesús, amén.",
"Senhor, enche-me de alegria na esperança que me deste. Dá-me paciência nas aflições e perseverança na oração. Não permitas que eu me canse de te buscar, mesmo quando as respostas demorarem. Em nome de Jesus, amém.")

E("60.3.13", "Cielos nuevos y tierra nueva", "Novos céus e nova terra",
"En este capítulo, Pedro responde a los burladores que decían que Cristo no volvería. Explica que Dios no tarda, sino que es paciente, porque quiere que todos procedan al arrepentimiento. Y luego afirma la esperanza del creyente: «esperamos cielos nuevos y tierra nueva, según sus promesas, en los cuales mora la justicia». Este mundo, marcado por la injusticia, no tiene la última palabra. Dios prepara una creación donde la justicia no estará de visita, sino que habitará de forma permanente. Por eso el versículo siguiente nos exhorta a procurar ser hallados en paz, sin mancha. La esperanza del futuro no nos aparta del presente; nos motiva a vivir hoy con santidad y a anunciar el evangelio mientras dura la paciencia de Dios.",
"Neste capítulo, Pedro responde aos zombadores que diziam que Cristo não voltaria. Ele explica que Deus não demora, mas é paciente, porque quer que todos cheguem ao arrependimento. E então afirma a esperança do crente: «aguardamos novos céus e nova terra, em que a justiça habita». Este mundo, marcado pela injustiça, não tem a última palavra. Deus prepara uma criação onde a justiça não estará de visita, mas morará de forma permanente. Por isso o versículo seguinte nos exorta a procurar ser achados em paz, sem mácula. A esperança do futuro não nos afasta do presente; ela nos motiva a viver hoje com santidade e a anunciar o evangelho enquanto dura a paciência de Deus.",
"Ore hoy por una persona que aún no conoce a Cristo, aprovechando el tiempo de la paciencia de Dios.",
"Ore hoje por uma pessoa que ainda não conhece a Cristo, aproveitando o tempo da paciência de Deus.",
"Señor, gracias por la promesa de cielos nuevos y tierra nueva donde morará la justicia. Mientras espero ese día, ayúdame a vivir en santidad y en paz, y a hablar de Cristo a quienes todavía no le conocen. En el nombre de Jesús, amén.",
"Senhor, obrigado pela promessa de novos céus e nova terra onde a justiça habitará. Enquanto espero esse dia, ajuda-me a viver em santidade e em paz, e a falar de Cristo a quem ainda não o conhece. Em nome de Jesus, amém.")
# --- Días 311-328 ---
E("57.4.16", "Confianza ante el trono", "Confiança diante do trono",
"La carta a los Hebreos presenta a Jesús como nuestro gran sumo sacerdote. El versículo anterior dice que Él puede compadecerse de nuestras debilidades, porque fue tentado en todo, pero sin pecado. Por eso la invitación es directa: «lleguémonos pues confiadamente al trono de la gracia». En el Antiguo Testamento, pocos podían acercarse al lugar santísimo, y con temor. Ahora, por medio de Cristo, el trono de Dios es llamado trono de gracia. Allí usted no encuentra un juez impaciente, sino misericordia para sus fallas y gracia «para el oportuno socorro», es decir, ayuda en el momento justo. No espere a sentirse digno para orar. Precisamente cuando se siente débil es cuando más necesita acercarse, y la puerta está abierta.",
"A carta aos Hebreus apresenta Jesus como o nosso grande sumo sacerdote. O versículo anterior diz que ele pode se compadecer das nossas fraquezas, porque foi tentado em tudo, mas sem pecado. Por isso o convite é direto: «acheguemo-nos com confiança ao trono da graça». No Antigo Testamento, poucos podiam se aproximar do lugar santíssimo, e com temor. Agora, por meio de Cristo, o trono de Deus é chamado trono da graça. Ali você não encontra um juiz impaciente, mas misericórdia para as suas falhas e graça para ser socorrido «no tempo adequado», isto é, ajuda na hora certa. Não espere se sentir digno para orar. Justamente quando você se sente fraco é quando mais precisa se aproximar, e a porta está aberta.",
"Presente hoy a Dios, con confianza, aquella necesidad que ha estado guardando por vergüenza.",
"Apresente hoje a Deus, com confiança, aquela necessidade que você vem guardando por vergonha.",
"Padre, gracias porque por medio de Jesús puedo acercarme sin miedo. Hoy vengo con mis debilidades y necesidades. Dame misericordia para mis faltas y gracia para el socorro que necesito en este momento. En el nombre de Jesús, amén.",
"Pai, obrigado porque, por meio de Jesus, posso me aproximar sem medo. Hoje venho com minhas fraquezas e necessidades. Dá-me misericórdia para minhas faltas e graça para o socorro de que preciso neste momento. Em nome de Jesus, amém.")

E("44.8.15-16", "Hijos, no esclavos", "Filhos, não escravos",
"Muchos creyentes viven su fe como siervos asustados, esperando el castigo ante cada error. Pablo dice que no recibimos «el espíritu de servidumbre para estar otra vez en temor», sino «el espíritu de adopción». En aquel tiempo, un hijo adoptado recibía plenos derechos en la familia. Así nos ve Dios en Cristo. Por eso clamamos «Abba, Padre», una expresión de cercanía y confianza. Y el Espíritu Santo mismo «da testimonio a nuestro espíritu» de que somos hijos de Dios. No es solo una doctrina para aprender, sino una certeza interior que el Espíritu confirma. Hoy usted puede orar no como quien pide audiencia a un rey lejano, sino como un hijo que se acerca a su Padre que le ama.",
"Muitos crentes vivem sua fé como servos assustados, esperando castigo a cada erro. Paulo diz que não recebemos «o espírito de escravidão, para voltardes ao medo», mas «o Espírito de adoção». Naquele tempo, um filho adotado recebia direitos plenos na família. É assim que Deus nos vê em Cristo. Por isso clamamos «Aba, Pai», uma expressão de proximidade e confiança. E o próprio Espírito Santo «dá testemunho com o nosso espírito» de que somos filhos de Deus. Não é apenas uma doutrina para aprender, mas uma certeza interior que o Espírito confirma. Hoje você pode orar não como quem pede audiência a um rei distante, mas como um filho que se aproxima do seu Pai que o ama.",
"Comience su oración hoy llamando a Dios «Padre» y háblele con la confianza de un hijo.",
"Comece sua oração hoje chamando Deus de «Pai» e fale com ele com a confiança de um filho.",
"Padre, gracias porque me adoptaste en Cristo. Quita de mi corazón el temor de esclavo y lléname de la confianza de un hijo. Espíritu Santo, confirma en mí que pertenezco a la familia de Dios. En el nombre de Jesús, amén.",
"Pai, obrigado porque me adotaste em Cristo. Tira do meu coração o medo de escravo e enche-me da confiança de filho. Espírito Santo, confirma em mim que pertenço à família de Deus. Em nome de Jesus, amém.")

E("44.12.4-5", "Diferentes, pero un cuerpo", "Diferentes, mas um só corpo",
"Pablo acaba de pedir que nadie tenga de sí mismo un concepto más alto del que debe tener. Luego explica por qué: somos como un cuerpo con muchos miembros, y «todos los miembros no tienen la misma operación». El ojo no hace el trabajo de la mano, ni el pie el del oído. Esto libra al creyente de dos errores: creerse indispensable y despreciar a los demás, o sentirse inútil porque no tiene el don de otro. La frase final es fuerte: somos «miembros los unos de los otros». Usted no solo pertenece a Cristo; también pertenece a sus hermanos, y ellos a usted. Los versículos siguientes enumeran dones distintos. Lo importante no es cuál le tocó, sino usarlo con fidelidad para el bien de todos.",
"Paulo acaba de pedir que ninguém tenha de si mesmo um conceito mais alto do que deve ter. Depois explica por quê: somos como um corpo com muitos membros, e «nem todos os membros têm a mesma função». O olho não faz o trabalho da mão, nem o pé o do ouvido. Isso livra o crente de dois erros: achar-se indispensável e desprezar os outros, ou sentir-se inútil porque não tem o dom de outro. A frase final é forte: somos «membros uns dos outros». Você não pertence apenas a Cristo; pertence também aos seus irmãos, e eles a você. Os versículos seguintes listam dons diferentes. O importante não é qual coube a você, mas usá-lo com fidelidade para o bem de todos.",
"Agradezca hoy a Dios por el don de un hermano que es muy distinto a usted, y dígaselo a esa persona.",
"Agradeça hoje a Deus pelo dom de um irmão que é muito diferente de você, e diga isso a essa pessoa.",
"Señor, gracias porque me hiciste parte del cuerpo de Cristo. Líbrame del orgullo y del sentimiento de inutilidad. Ayúdame a valorar los dones de mis hermanos y a usar con fidelidad el que me has dado. En el nombre de Jesús, amén.",
"Senhor, obrigado porque me fizeste parte do corpo de Cristo. Livra-me do orgulho e do sentimento de inutilidade. Ajuda-me a valorizar os dons dos meus irmãos e a usar com fidelidade o que me deste. Em nome de Jesus, amém.")

E("46.4.17-18", "Mirando lo que no se ve", "Olhando para o invisível",
"Pablo no escribe desde la comodidad. En los versículos anteriores habla de estar atribulado, perseguido y derribado. Aun así, llama a su tribulación «momentánea y leve». No porque fuera pequeña, sino porque la comparó con algo mucho mayor: «un sobremanera alto y eterno peso de gloria». El secreto está en el versículo dieciocho: no mirar «a las cosas que se ven», que son temporales, sino a las que no se ven, que son eternas. Lo que usted ve hoy, como la enfermedad, la deuda o la soledad, es real, pero no es definitivo. Lo invisible, la presencia de Dios, sus promesas y la gloria venidera, es lo que permanece. Cuando la mirada cambia de lugar, la carga no desaparece, pero cambia de peso.",
"Paulo não escreve a partir do conforto. Nos versículos anteriores ele fala de estar atribulado, perseguido e abatido. Mesmo assim, chama sua aflição de «leve e momentânea». Não porque fosse pequena, mas porque a comparou com algo muito maior: «um peso eterno de excelentíssima glória». O segredo está no versículo dezoito: não prestar atenção às coisas visíveis, que são temporárias, mas às invisíveis, que são eternas. O que você vê hoje, como a doença, a dívida ou a solidão, é real, mas não é definitivo. O invisível, a presença de Deus, suas promessas e a glória futura, é o que permanece. Quando o olhar muda de lugar, o fardo não desaparece, mas muda de peso.",
"Escriba una promesa de Dios y léala cada vez que la dificultad de hoy le parezca demasiado grande.",
"Escreva uma promessa de Deus e leia-a sempre que a dificuldade de hoje lhe parecer grande demais.",
"Señor, a veces solo veo los problemas que me rodean. Abre los ojos de mi fe para mirar lo eterno. Dame fuerzas para soportar la aflición de hoy, sabiendo que me espera una gloria mucho mayor. En el nombre de Jesús, amén.",
"Senhor, às vezes só vejo os problemas ao meu redor. Abre os olhos da minha fé para olhar o eterno. Dá-me forças para suportar a aflição de hoje, sabendo que me espera uma glória muito maior. Em nome de Jesus, amém.")

E("60.1.5-7", "Una fe que crece", "Uma fé que cresce",
"Pedro acaba de decir que Dios nos dio «todas las cosas que pertenecen a la vida y a la piedad». Pero eso no nos vuelve pasivos. Al contrario: «poniendo toda diligencia», debemos añadir a la fe virtud, conocimiento, dominio propio, paciencia, piedad, afecto fraternal y amor. Es como una escalera donde cada peldaño se apoya en el anterior. La fe es el punto de partida, y el amor es la cumbre. La vida cristiana no se queda estancada en el día de la conversión; crece con esfuerzo, apoyada en la gracia. El versículo ocho advierte que, si estas cosas abundan, no seremos ociosos ni sin fruto. Hoy usted puede preguntarse: ¿en cuál de estas áreas necesito crecer? Dios da la gracia; a usted le toca la diligencia.",
"Pedro acaba de dizer que Deus nos deu tudo o que diz respeito à vida e à piedade. Mas isso não nos torna passivos. Pelo contrário: «pondo todo o empenho», devemos acrescentar à fé virtude, conhecimento, domínio próprio, paciência, devoção, amor fraternal e amor. É como uma escada em que cada degrau se apoia no anterior. A fé é o ponto de partida, e o amor é o topo. A vida cristã não fica parada no dia da conversão; ela cresce com esforço, apoiada na graça. O versículo oito adverte que, se essas coisas abundarem, não seremos ociosos nem infrutíferos. Hoje você pode se perguntar: em qual dessas áreas preciso crescer? Deus dá a graça; a você cabe o empenho.",
"Escoja una de las virtudes de la lista y practíquela de manera intencional durante esta semana.",
"Escolha uma das virtudes da lista e pratique-a de forma intencional durante esta semana.",
"Señor, gracias por la fe que me diste. No quiero quedarme estancado. Ayúdame a añadir a mi fe virtud, dominio propio, paciencia y amor, para que mi vida dé fruto y honre el nombre de Cristo. En el nombre de Jesús, amén.",
"Senhor, obrigado pela fé que me deste. Não quero ficar parado. Ajuda-me a acrescentar à minha fé virtude, domínio próprio, paciência e amor, para que minha vida dê fruto e honre o nome de Cristo. Em nome de Jesus, amém.")

E("61.3.2-3", "Seremos semejantes a Él", "Seremos semelhantes a ele",
"Juan escribe con asombro: «ahora somos hijos de Dios». No dice que lo seremos algún día, sino que ya lo somos. Sin embargo, reconoce que todavía «no se ha manifestado lo que hemos de ser». Hay una obra que Dios aún no ha terminado en nosotros. La promesa es gloriosa: cuando Cristo aparezca, «seremos semejantes a él, porque le veremos como él es». Y esta esperanza tiene un efecto práctico inmediato: «cualquiera que tiene esta esperanza en él, se purifica». Quien espera a Cristo no vive de cualquier manera. Usted no se purifica para ganar el amor de Dios, sino porque ya es su hijo y anhela parecerse a Aquel que verá cara a cara. La esperanza del futuro limpia el presente.",
"João escreve com admiração: «agora somos filhos de Deus». Ele não diz que seremos algum dia, mas que já somos. No entanto, reconhece que ainda «não está manifesto o que seremos». Há uma obra que Deus ainda não terminou em nós. A promessa é gloriosa: quando Cristo se manifestar, seremos semelhantes a ele, porque o veremos como ele é. E essa esperança tem um efeito prático imediato: «todo aquele que tem nele essa esperança purifica a si mesmo». Quem espera Cristo não vive de qualquer jeito. Você não se purifica para ganhar o amor de Deus, mas porque já é filho dele e deseja se parecer com aquele que verá face a face. A esperança do futuro limpa o presente.",
"Pida a Dios que le muestre un hábito que debe abandonar para vivir con mayor pureza.",
"Peça a Deus que lhe mostre um hábito que você precisa abandonar para viver com mais pureza.",
"Padre, gracias porque ya soy hijo de Dios. Anhelo el día en que veré a Cristo y seré semejante a Él. Mientras tanto, purifica mi corazón y mis caminos, para que mi vida refleje esta esperanza. En el nombre de Jesús, amén.",
"Pai, obrigado porque já sou filho de Deus. Anseio pelo dia em que verei Cristo e serei semelhante a ele. Enquanto isso, purifica meu coração e meus caminhos, para que minha vida reflita esta esperança. Em nome de Jesus, amém.")

E("46.5.17", "Todo es hecho nuevo", "Tudo se fez novo",
"Pablo explica que ya no conoce a nadie según la carne, es decir, con criterios meramente humanos. La razón es esta: «si alguno está en Cristo, nueva criatura es». No se trata de una mejora de lo viejo ni de un cambio de costumbres solamente. Es una nueva creación, obra de Dios. «Las cosas viejas pasaron». Su pasado no define quién es usted en Cristo. Y luego viene un «he aquí», como quien invita a mirar con atención: «todas son hechas nuevas». Los versículos siguientes dicen que todo esto proviene de Dios, que nos reconcilió consigo. Quizás otros le sigan recordando lo que usted fue. Dios le mira según lo que Él hizo en usted. Viva hoy de acuerdo con esa nueva identidad.",
"Paulo explica que já não conhece ninguém segundo a carne, isto é, com critérios meramente humanos. A razão é esta: «se alguém está em Cristo, uma nova criatura é». Não se trata de uma melhoria do velho nem apenas de uma mudança de costumes. É uma nova criação, obra de Deus. «As coisas velhas já passaram». O seu passado não define quem você é em Cristo. E depois vem um «eis», como quem convida a olhar com atenção: «tudo se fez novo». Os versículos seguintes dizem que tudo isso vem de Deus, que nos reconciliou consigo. Talvez outros continuem lembrando o que você foi. Deus olha para você segundo o que ele fez em você. Viva hoje de acordo com essa nova identidade.",
"Cuando hoy le venga a la mente un recuerdo del pasado que le acusa, responda con este versículo.",
"Quando hoje vier à mente uma lembrança do passado que o acusa, responda com este versículo.",
"Señor, gracias porque en Cristo soy una nueva criatura. Lo viejo pasó y me has dado una vida nueva. Ayúdame a no vivir atado a mi pasado, sino a caminar cada día en la identidad que me diste. En el nombre de Jesús, amén.",
"Senhor, obrigado porque em Cristo sou uma nova criatura. O velho passou e me deste uma vida nova. Ajuda-me a não viver preso ao meu passado, mas a andar cada dia na identidade que me deste. Em nome de Jesus, amém.")

E("57.10.24-25", "No deje de congregarse", "Não deixe de congregar",
"El autor de Hebreos acaba de hablar del acceso libre que tenemos a Dios por la sangre de Jesús. Pero la fe no es solo vertical; también es comunitaria. Por eso añade: «considerémonos los unos a los otros para provocarnos al amor y a las buenas obras». Considerar es prestar atención, conocer a los hermanos lo suficiente como para animarlos. Y advierte sobre un peligro antiguo: dejar de congregarse, «como algunos tienen por costumbre». El cansancio, las heridas o la rutina pueden llevar a alguien a apartarse poco a poco. Pero el creyente aislado se enfría con facilidad. La reunión de la iglesia es un lugar para exhortarnos, y esto se vuelve más urgente «cuanto veis que aquel día se acerca». Su presencia anima a otros.",
"O autor de Hebreus acaba de falar do livre acesso que temos a Deus pelo sangue de Jesus. Mas a fé não é apenas vertical; ela também é comunitária. Por isso ele acrescenta: «sejamos atenciosos uns para com os outros, a fim de incentivar o amor e as boas obras». Ser atencioso é prestar atenção, conhecer os irmãos o suficiente para animá-los. E ele adverte sobre um perigo antigo: abandonar a reunião, «como é o costume de alguns». O cansaço, as feridas ou a rotina podem levar alguém a se afastar aos poucos. Mas o crente isolado esfria com facilidade. A reunião da igreja é um lugar para encorajar uns aos outros, e isso se torna mais urgente «quanto vedes aquele dia se aproximando». A sua presença anima outros.",
"Busque a un hermano que ha dejado de congregarse y anímelo con una visita o un mensaje.",
"Procure um irmão que deixou de congregar e anime-o com uma visita ou uma mensagem.",
"Señor, gracias por mi iglesia. Líbrame de la frialdad y del aislamiento. Dame ojos para ver a los hermanos que se están apartando y palabras para animarlos al amor y a las buenas obras. En el nombre de Jesús, amén.",
"Senhor, obrigado pela minha igreja. Livra-me da frieza e do isolamento. Dá-me olhos para ver os irmãos que estão se afastando e palavras para animá-los ao amor e às boas obras. Em nome de Jesus, amém.")

E("48.6.16-17", "Escudo, yelmo y espada", "Escudo, capacete e espada",
"Pablo completa la armadura con tres piezas decisivas. El escudo de la fe apaga «todos los dardos de fuego del maligno»: la duda, la acusación, el miedo y la mentira. No es una fe en nosotros mismos, sino confianza en lo que Dios dijo. El yelmo de la salvación protege la mente con la certeza de que pertenecemos a Cristo. Y la espada del Espíritu, «que es la palabra de Dios», es la única pieza para atacar. Jesús mismo venció la tentación en el desierto respondiendo «escrito está». Usted no enfrenta las batallas espirituales con opiniones, sino con la Palabra. Por eso es tan importante leerla y guardarla en el corazón. Una espada que nunca se toma no sirve en la hora del combate.",
"Paulo completa a armadura com três peças decisivas. O escudo da fé apaga «todas as flechas inflamadas do maligno»: a dúvida, a acusação, o medo e a mentira. Não é uma fé em nós mesmos, mas confiança no que Deus disse. O capacete da salvação protege a mente com a certeza de que pertencemos a Cristo. E a espada do Espírito, «que é a palavra de Deus», é a única peça para atacar. O próprio Jesus venceu a tentação no deserto respondendo «está escrito». Você não enfrenta as batalhas espirituais com opiniões, mas com a Palavra. Por isso é tão importante lê-la e guardá-la no coração. Uma espada que nunca é empunhada não serve na hora do combate.",
"Memorice hoy un versículo que responda a la tentación o al temor que más le ataca.",
"Memorize hoje um versículo que responda à tentação ou ao medo que mais o ataca.",
"Señor, aumenta mi fe para apagar los dardos del enemigo. Guarda mi mente con la certeza de la salvación y enséñame a usar la Palabra como espada. Que en cada batalla mi respuesta sea: escrito está. En el nombre de Jesús, amén.",
"Senhor, aumenta minha fé para apagar as flechas do inimigo. Guarda minha mente com a certeza da salvação e ensina-me a usar a Palavra como espada. Que em cada batalha minha resposta seja: está escrito. Em nome de Jesus, amém.")

E("48.5.18", "Llenos del Espíritu", "Cheios do Espírito",
"Pablo hace un contraste llamativo. El vino en exceso domina a la persona y la lleva a la disolución. En cambio, el creyente es llamado a estar «lleno del Espíritu», es decir, bajo la influencia y el control del Espíritu Santo. En el griego, el verbo indica una acción continua: seguir siendo llenos. No es una experiencia de un solo día, sino una vida que busca constantemente la presencia de Dios. Los versículos siguientes muestran cómo se nota esta llenura: cánticos y alabanza, gratitud en todo y sujeción mutua en el temor de Dios. La llenura del Espíritu no se ve solo en el culto, sino en el hogar y en el trabajo. Hoy usted puede abrir su corazón y pedir más de Él.",
"Paulo faz um contraste marcante. O vinho em excesso domina a pessoa e a leva à devassidão. Por outro lado, o crente é chamado a estar «cheio do Espírito», isto é, sob a influência e o controle do Espírito Santo. No grego, o verbo indica uma ação contínua: continuar sendo cheios. Não é uma experiência de um único dia, mas uma vida que busca constantemente a presença de Deus. Os versículos seguintes mostram como essa plenitude aparece: cânticos e louvor, gratidão em tudo e sujeição mútua no temor de Deus. A plenitude do Espírito não se vê apenas no culto, mas no lar e no trabalho. Hoje você pode abrir o seu coração e pedir mais dele.",
"Dedique un tiempo hoy a adorar a Dios con un cántico y a pedir ser lleno del Espíritu Santo.",
"Dedique um tempo hoje para adorar a Deus com um cântico e pedir para ser cheio do Espírito Santo.",
"Espíritu Santo, quiero ser lleno de ti cada día. Toma el control de mis pensamientos, palabras y acciones. Que mi casa y mi trabajo reflejen la presencia de Dios con alabanza, gratitud y humildad. En el nombre de Jesús, amén.",
"Espírito Santo, quero ser cheio de ti a cada dia. Toma o controle dos meus pensamentos, palavras e ações. Que minha casa e meu trabalho reflitam tua presença com louvor, gratidão e humildade. Em nome de Jesus, amém.")

E("46.12.9", "Gracia suficiente", "Graça suficiente",
"Pablo pidió tres veces que Dios le quitara un «aguijón en la carne». No sabemos exactamente qué era, pero sí sabemos que le causaba gran sufrimiento. La respuesta de Dios no fue quitarlo, sino darle algo mejor: «bástate mi gracia; porque mi potencia en la flaqueza se perfecciona». A veces Dios responde a nuestra oración cambiando la circunstancia; otras veces nos cambia a nosotros dentro de ella. Pablo aprendió a ver su debilidad de otra manera: como el lugar donde reposa el poder de Cristo. Usted no necesita aparentar fuerza delante de Dios. La gracia que recibe hoy es suficiente para hoy. Su debilidad no es un obstáculo para Dios; puede convertirse en el escenario donde su poder se muestra con mayor claridad.",
"Paulo pediu três vezes que Deus lhe tirasse um «espinho na carne». Não sabemos exatamente o que era, mas sabemos que lhe causava grande sofrimento. A resposta de Deus não foi tirá-lo, mas dar algo melhor: «minha graça te basta, porque meu poder se aperfeiçoa na fraqueza». Às vezes Deus responde à nossa oração mudando a circunstância; outras vezes ele nos muda dentro dela. Paulo aprendeu a ver sua fraqueza de outra maneira: como o lugar onde repousa o poder de Cristo. Você não precisa aparentar força diante de Deus. A graça que você recebe hoje é suficiente para hoje. A sua fraqueza não é um obstáculo para Deus; ela pode se tornar o cenário onde o poder dele se mostra com mais clareza.",
"Presente a Dios honestamente su mayor debilidad y pídale gracia suficiente para el día de hoy.",
"Apresente a Deus honestamente a sua maior fraqueza e peça graça suficiente para o dia de hoje.",
"Señor, hay cargas que te pedí quitar y siguen conmigo. Ayúdame a confiar en que la gracia que me das es suficiente. Que en mi debilidad se vea el poder de Cristo, y que todo sea para la gloria de Dios. En el nombre de Jesús, amén.",
"Senhor, há fardos que te pedi para tirar e continuam comigo. Ajuda-me a confiar que a graça que me dás é suficiente. Que na minha fraqueza se veja o poder de Cristo, e que tudo seja para a glória de Deus. Em nome de Jesus, amém.")

E("44.5.8", "Amados siendo pecadores", "Amados quando éramos pecadores",
"Pablo observa que es difícil que alguien muera por un justo, aunque quizá alguno se atreva a morir por una persona buena. Pero Dios hizo algo que supera toda lógica humana: «siendo aún pecadores, Cristo murió por nosotros». Dios no esperó a que fuéramos mejores para amarnos. Nos amó cuando no teníamos nada que ofrecer. La palabra «encarece» indica que Dios demuestra, pone en evidencia su amor. La cruz es la prueba concreta. Cuando usted dude del amor de Dios porque fracasó o porque las cosas no salen como esperaba, mire a la cruz. Si Dios le amó en su peor momento, no dejará de amarle ahora que es su hijo. Ese amor no se basa en su desempeño, sino en el carácter de Dios.",
"Paulo observa que dificilmente alguém morreria por um justo, embora talvez alguém ousasse morrer por uma pessoa boa. Mas Deus fez algo que supera toda lógica humana: Cristo morreu por nós «quando ainda éramos pecadores». Deus não esperou que fôssemos melhores para nos amar. Ele nos amou quando não tínhamos nada a oferecer. A palavra «prova» indica que Deus demonstra, coloca em evidência o seu amor. A cruz é a prova concreta. Quando você duvidar do amor de Deus porque falhou ou porque as coisas não saíram como esperava, olhe para a cruz. Se Deus amou você no seu pior momento, não deixará de amá-lo agora que você é filho dele. Esse amor não se baseia no seu desempenho, mas no caráter de Deus.",
"Escriba en un papel «Cristo murió por mí» y guárdelo donde lo vea cuando se sienta indigno.",
"Escreva num papel «Cristo morreu por mim» e guarde-o onde você o veja quando se sentir indigno.",
"Padre, gracias porque me amaste cuando todavía era pecador. La cruz de Cristo me recuerda cuánto valgo para ti. Cuando dude de ese amor, ayúdame a mirar al Calvario y a descansar en él. En el nombre de Jesús, amén.",
"Pai, obrigado porque me amaste quando eu ainda era pecador. A cruz de Cristo me lembra o quanto valho para ti. Quando eu duvidar desse amor, ajuda-me a olhar para o Calvário e descansar nele. Em nome de Jesus, amém.")

E("45.15.57-58", "Su trabajo no es en vano", "Seu trabalho não é em vão",
"Después de un largo capítulo sobre la resurrección, Pablo estalla en gratitud: «a Dios gracias, que nos da la victoria por el Señor nuestro Jesucristo». La muerte ya no tiene la última palabra. Pero fíjese en la conclusión práctica que saca: «así que… estad firmes y constantes, creciendo en la obra del Señor siempre». La esperanza de la resurrección no lleva a la pasividad, sino a la perseverancia en el servicio. Muchas veces el trabajo en la obra de Dios parece invisible o sin resultados: una clase con pocos alumnos, una visita que nadie valora, una oración que parece no tener respuesta. Pablo asegura que nada de eso se pierde: «vuestro trabajo en el Señor no es vano». Dios ve y recompensará lo que usted hace por amor a Él.",
"Depois de um longo capítulo sobre a ressurreição, Paulo explode em gratidão: «graças a Deus, que nos dá vitória por meio do nosso Senhor Jesus Cristo». A morte já não tem a última palavra. Mas observe a conclusão prática que ele tira: «portanto… sede firmes, imóveis e sempre abundantes na obra do Senhor». A esperança da ressurreição não leva à passividade, mas à perseverança no serviço. Muitas vezes o trabalho na obra de Deus parece invisível ou sem resultados: uma classe com poucos alunos, uma visita que ninguém valoriza, uma oração que parece não ter resposta. Paulo garante que nada disso se perde: «o vosso trabalho não é vão no Senhor». Deus vê e recompensará o que você faz por amor a ele.",
"Retome hoy con ánimo una tarea en la obra de Dios que había dejado por desánimo.",
"Retome hoje com ânimo uma tarefa na obra de Deus que você tinha deixado por desânimo.",
"Señor, gracias por la victoria que nos das en Cristo sobre el pecado y la muerte. Cuando me sienta cansado en la obra, recuérdame que nada de lo que hago por amor a ti es en vano. Hazme firme y constante. En el nombre de Jesús, amén.",
"Senhor, obrigado pela vitória que nos dás em Cristo sobre o pecado e a morte. Quando eu me sentir cansado na obra, lembra-me de que nada do que faço por amor a ti é em vão. Torna-me firme e constante. Em nome de Jesus, amém.")

E("48.4.2-3", "Guardar la unidad", "Guardar a unidade",
"Pablo, preso por causa del evangelio, ruega a los efesios que anden como es digno de su llamamiento. ¿Y cómo se nota eso? No en grandes hazañas, sino en actitudes: humildad, mansedumbre, paciencia, soportándonos «los unos a los otros en amor». Luego añade una tarea: ser «solícitos a guardar la unidad del Espíritu en el vínculo de la paz». Observe que no dice «crear» la unidad, sino «guardarla». La unidad ya fue dada por el Espíritu; nuestra parte es cuidarla con diligencia. Se pierde con facilidad por un chisme, un orgullo herido o una palabra dura. Se guarda con humildad y paciencia. Usted puede ser hoy un guardián de la paz en su iglesia y en su familia, en vez de alguien que la rompe.",
"Paulo, preso por causa do evangelho, roga aos efésios que andem de modo digno do seu chamado. E como isso aparece? Não em grandes façanhas, mas em atitudes: humildade, mansidão, paciência, «tolerando uns aos outros em amor». Depois acrescenta uma tarefa: «procurai guardar a unidade do Espírito pelo vínculo da paz». Observe que ele não diz «criar» a unidade, mas «guardá-la». A unidade já foi dada pelo Espírito; a nossa parte é cuidar dela com diligência. Ela se perde com facilidade por uma fofoca, um orgulho ferido ou uma palavra dura. Ela se guarda com humildade e paciência. Hoje você pode ser um guardião da paz na sua igreja e na sua família, em vez de alguém que a rompe.",
"Evite hoy cualquier comentario que pueda dividir, y busque la paz con alguien con quien tuvo un roce.",
"Evite hoje qualquer comentário que possa dividir, e busque a paz com alguém com quem você teve um atrito.",
"Señor, hazme humilde, manso y paciente. Líbrame de las palabras que dividen y del orgullo que hiere. Ayúdame a guardar la unidad del Espíritu en mi iglesia y en mi hogar, en el vínculo de la paz. En el nombre de Jesús, amén.",
"Senhor, torna-me humilde, manso e paciente. Livra-me das palavras que dividem e do orgulho que fere. Ajuda-me a guardar a unidade do Espírito na minha igreja e no meu lar, pelo vínculo da paz. Em nome de Jesus, amém.")

E("44.8.28", "Dios obra para bien", "Deus age para o bem",
"Este versículo es uno de los más citados, y a veces se usa como si dijera que todo lo que sucede es bueno. No es eso lo que afirma. Pablo acaba de hablar de los gemidos de la creación y de nuestra propia debilidad. Él reconoce que hay dolor real. Lo que asegura es que Dios es capaz de hacer que «todas las cosas les ayuden a bien» a los que le aman. Y el versículo siguiente explica cuál es ese bien: ser hechos conformes a la imagen de su Hijo. Dios no siempre nos da el resultado que esperamos, pero nunca desperdicia nada. Incluso lo que otros pensaron para mal, Él lo usa para formar a Cristo en usted. Esa es una seguridad para los días oscuros.",
"Este versículo é um dos mais citados, e às vezes é usado como se dissesse que tudo o que acontece é bom. Não é isso que ele afirma. Paulo acaba de falar dos gemidos da criação e da nossa própria fraqueza. Ele reconhece que há dor real. O que ele garante é que Deus é capaz de fazer com que «todas as coisas juntamente contribuam para o bem» daqueles que o amam. E o versículo seguinte explica qual é esse bem: sermos feitos conforme a imagem do seu Filho. Deus nem sempre nos dá o resultado que esperamos, mas nunca desperdiça nada. Até o que outros planejaram para o mal, ele usa para formar Cristo em você. Essa é uma segurança para os dias escuros.",
"Entregue hoy a Dios una situación que no entiende, diciendo: «Confío en que la usará para mi bien».",
"Entregue hoje a Deus uma situação que você não entende, dizendo: «Confio que ele a usará para o meu bem».",
"Padre, hay cosas en mi vida que no entiendo. Pero confío en que obras en todas ellas para mi bien. Úsalas para hacerme más parecido a Cristo, y dame paz mientras espero ver el propósito de todo. En el nombre de Jesús, amén.",
"Pai, há coisas na minha vida que não entendo. Mas confio que tu ages em todas elas para o meu bem. Usa-as para me tornar mais parecido com Cristo, e dá-me paz enquanto espero ver o teu propósito. Em nome de Jesus, amém.")

E("58.5.7-8", "Paciencia del labrador", "A paciência do lavrador",
"Santiago escribe a creyentes que sufrían injusticias, incluso de parte de ricos que retenían el salario de los trabajadores. Su consejo es: «tened paciencia hasta la venida del Señor». Para explicarlo, usa la imagen del labrador. Él siembra, trabaja, pero no puede hacer llover. Espera con paciencia la lluvia temprana y la tardía, confiando en que el fruto vendrá. Así es la vida del creyente: hacemos lo que nos corresponde y esperamos en Dios. «Confirmad vuestros corazones», es decir, fortalezcan su interior, «porque la venida del Señor se acerca». La certeza de que Cristo vendrá y hará justicia le permite a usted no amargarse ni tomar venganza. El labrador no arranca la semilla para ver si está creciendo; confía y espera.",
"Tiago escreve a crentes que sofriam injustiças, inclusive por parte de ricos que retinham o salário dos trabalhadores. Seu conselho é: «sede pacientes até a vinda do Senhor». Para explicar, ele usa a imagem do lavrador. Ele semeia, trabalha, mas não pode fazer chover. Espera com paciência as chuvas temporãs e serôdias, confiando que o fruto virá. Assim é a vida do crente: fazemos a nossa parte e esperamos em Deus. «Fortalecei os vossos corações», isto é, firmem o seu interior, «porque a vinda do Senhor está próxima». A certeza de que Cristo virá e fará justiça permite que você não se amargure nem se vingue. O lavrador não arranca a semente para ver se ela está crescendo; ele confia e espera.",
"Ante una injusticia que está viviendo, entréguela hoy a Dios y renuncie a la venganza.",
"Diante de uma injustiça que você está vivendo, entregue-a hoje a Deus e renuncie à vingança.",
"Señor, dame la paciencia del labrador. Ayúdame a hacer mi parte y a esperar en ti sin amargura. Fortalece mi corazón con la certeza de que Cristo viene y que harás justicia a su tiempo. En el nombre de Jesús, amén.",
"Senhor, dá-me a paciência do lavrador. Ajuda-me a fazer a minha parte e a esperar em ti sem amargura. Fortalece meu coração com a certeza de que Cristo vem e que farás justiça no tempo certo. Em nome de Jesus, amém.")

E("44.6.4", "Andar en vida nueva", "Andar em vida nova",
"Algunos en Roma preguntaban: si la gracia abunda donde abunda el pecado, ¿por qué no seguir pecando? Pablo responde con firmeza: «en ninguna manera». Y explica el significado del bautismo. Al ser bautizados, fuimos identificados con Cristo en su muerte y sepultura. Pero la historia no termina en la tumba: así como Cristo resucitó por la gloria del Padre, «así también nosotros andemos en novedad de vida». El bautismo en agua es un testimonio público de algo que Dios hizo por dentro: lo viejo murió y una vida nueva comenzó. La gracia no es un permiso para pecar, sino el poder para vivir distinto. Hoy usted puede recordar que ya no está obligado a obedecer al pecado. Pertenece a Aquel que venció la muerte.",
"Alguns em Roma perguntavam: se a graça transborda onde abunda o pecado, por que não continuar pecando? Paulo responde com firmeza: «de modo nenhum». E explica o significado do batismo. Ao sermos batizados, fomos identificados com Cristo em sua morte e sepultamento. Mas a história não termina no túmulo: assim como Cristo ressuscitou pela glória do Pai, assim também nós devemos andar em novidade de vida. O batismo nas águas é um testemunho público de algo que Deus fez por dentro: o velho morreu e uma vida nova começou. A graça não é uma permissão para pecar, mas o poder para viver de modo diferente. Hoje você pode lembrar que já não é obrigado a obedecer ao pecado. Você pertence àquele que venceu a morte.",
"Recuerde hoy su bautismo y dé gracias a Dios por la vida nueva que le dio en Cristo.",
"Lembre hoje o seu batismo e agradeça a Deus pela vida nova que ele lhe deu em Cristo.",
"Señor, gracias porque morí con Cristo y resucité con Él a una vida nueva. No quiero usar la gracia como excusa para pecar. Dame poder para andar cada día en novedad de vida, para la gloria del Padre. En el nombre de Jesús, amén.",
"Senhor, obrigado porque morri com Cristo e ressuscitei com ele para uma vida nova. Não quero usar a graça como desculpa para pecar. Dá-me poder para andar cada dia em novidade de vida, para a glória do Pai. Em nome de Jesus, amém.")

E("45.3.16", "Templo del Espíritu Santo", "Templo do Espírito Santo",
"Los corintios estaban divididos, cada grupo siguiendo a su líder preferido. Pablo les recuerda una verdad que debía cambiar su manera de tratarse: «¿No sabéis que sois templo de Dios, y que el Espíritu de Dios mora en vosotros?». En este pasaje, el templo es la iglesia como comunidad; en el capítulo seis, Pablo aplica la misma idea al cuerpo de cada creyente. En ambos casos, el mensaje es serio: Dios habita en medio de su pueblo. Por eso el versículo siguiente advierte que quien destruye el templo de Dios será juzgado. Dividir la iglesia o contaminarla no es poca cosa. Hoy usted puede tratar a sus hermanos como lugar donde Dios habita, y cuidar su propia vida con la misma reverencia.",
"Os coríntios estavam divididos, cada grupo seguindo seu líder preferido. Paulo lembra uma verdade que deveria mudar a maneira como se tratavam: «Não sabeis vós, que sois o templo de Deus? E que o Espírito de Deus habita em vós?». Nesta passagem, o templo é a igreja como comunidade; no capítulo seis, Paulo aplica a mesma ideia ao corpo de cada crente. Nos dois casos, a mensagem é séria: Deus habita no meio do seu povo. Por isso o versículo seguinte adverte que quem destrói o templo de Deus será julgado. Dividir a igreja ou contaminá-la não é pouca coisa. Hoje você pode tratar seus irmãos como lugar onde Deus habita, e cuidar da sua própria vida com a mesma reverência.",
"Hable hoy de su iglesia solo con palabras que edifiquen, recordando que allí habita Dios.",
"Fale hoje da sua igreja somente com palavras que edifiquem, lembrando que ali Deus habita.",
"Señor, gracias porque el Espíritu de Dios habita en medio de su pueblo. Perdona cuando he tratado a la iglesia con ligereza. Ayúdame a cuidar la unidad de mis hermanos y la santidad de mi propia vida, como templo de Dios. En el nombre de Jesús, amén.",
"Senhor, obrigado porque o teu Espírito habita no teu povo. Perdoa quando tratei a igreja com descuido. Ajuda-me a cuidar da unidade dos meus irmãos e da santidade da minha própria vida, como templo de Deus. Em nome de Jesus, amém.")
# --- Días 329-346 ---
E("49.4.4", "Gozo que no depende", "Alegria que não depende",
"Pablo escribe esta carta desde la prisión, sin saber si saldría con vida. Y aun así repite: «gozaos en el Señor siempre: otra vez digo: que os gocéis». No es un optimismo forzado ni una negación de la realidad. La clave está en dos palabras: «en el Señor». El gozo cristiano no nace de que todo vaya bien, sino de la relación con Cristo, que no cambia con las circunstancias. Las cosas pueden faltar, las personas pueden fallar, pero el Señor permanece. Por eso el gozo es posible «siempre». Pablo lo repite porque sabe que lo olvidamos con facilidad. Hoy, aunque haya motivos de tristeza, usted puede encontrar en Cristo razones firmes para alegrarse: su perdón, su presencia y sus promesas.",
"Paulo escreve esta carta da prisão, sem saber se sairia com vida. E mesmo assim repete: «alegrai-vos sempre no Senhor. Volto a dizer: alegrai-vos». Não é um otimismo forçado nem uma negação da realidade. A chave está em duas palavras: «no Senhor». A alegria cristã não nasce de tudo estar bem, mas do relacionamento com Cristo, que não muda com as circunstâncias. As coisas podem faltar, as pessoas podem falhar, mas o Senhor permanece. Por isso a alegria é possível «sempre». Paulo repete porque sabe que esquecemos com facilidade. Hoje, mesmo que haja motivos de tristeza, você pode encontrar em Cristo razões firmes para se alegrar: o seu perdão, a sua presença e as suas promessas.",
"Haga una lista de tres razones para alegrarse en el Señor que no dependen de sus circunstancias.",
"Faça uma lista de três razões para se alegrar no Senhor que não dependem das suas circunstâncias.",
"Señor, aun en los días difíciles quiero alegrarme en ti. Gracias porque eres el mismo cuando todo cambia. Llena mi corazón de un gozo que no dependa de lo que tengo, sino de quién eres para mí. En el nombre de Jesús, amén.",
"Senhor, mesmo nos dias difíceis quero me alegrar em ti. Obrigado porque és o mesmo quando tudo muda. Enche meu coração de uma alegria que não dependa do que tenho, mas de quem tu és para mim. Em nome de Jesus, amém.")

E("59.5.8-9", "Sobrios, vigilantes y firmes", "Sóbrios, vigilantes e firmes",
"Pedro advierte con claridad: «vuestro adversario el diablo, cual león rugiente, anda alrededor buscando a quien devore». El león suele atacar al que se aparta del grupo o al que está distraído. Por eso la instrucción comienza con dos verbos: «sed templados, y velad». Templanza es tener la mente clara, sin dejarse arrastrar por excesos; velar es estar atento. Luego viene la acción: «resistid firmes en la fe». No dice que huyamos con miedo, sino que resistamos con la confianza puesta en Dios. Y añade un consuelo: los mismos padecimientos los sufren los hermanos en todo el mundo. Usted no es el único que lucha. El versículo diez promete que, después de un poco de tiempo, Dios mismo le perfeccionará, afirmará y fortalecerá.",
"Pedro adverte com clareza: «o vosso adversário, o diabo, anda ao redor, rugindo como um leão, buscando a quem possa devorar». O leão costuma atacar quem se afasta do grupo ou quem está distraído. Por isso a instrução começa com dois verbos: «sede sóbrios! Vigiai!». Sobriedade é ter a mente clara, sem se deixar levar por excessos; vigiar é estar atento. Depois vem a ação: «resisti a ele, firmes na fé». Ele não diz que devemos fugir com medo, mas resistir com a confiança posta em Deus. E acrescenta um consolo: as mesmas aflições acontecem com os irmãos em todo o mundo. Você não é o único que luta. O versículo dez promete que, depois de um pouco de tempo, o próprio Deus vai aperfeiçoar, firmar e fortalecer você.",
"Identifique un momento del día en que suele estar espiritualmente distraído y dedíquelo hoy a la oración.",
"Identifique um momento do dia em que você costuma estar espiritualmente distraído e dedique-o hoje à oração.",
"Señor, dame una mente sobria y un corazón vigilante. Ayúdame a resistir al enemigo firme en la fe, sin miedo. Gracias porque no estoy solo en esta lucha y porque al final me afirmarás y fortalecerás. En el nombre de Jesús, amén.",
"Senhor, dá-me uma mente sóbria e um coração vigilante. Ajuda-me a resistir ao inimigo firme na fé, sem medo. Obrigado porque não estou sozinho nesta luta e porque no fim me firmarás e fortalecerás. Em nome de Jesus, amém.")

E("47.6.2", "Llevar las cargas juntos", "Levar os fardos juntos",
"El versículo anterior habla de restaurar con mansedumbre al hermano que cayó en alguna falta. Luego Pablo amplía el principio: «sobrellevad los unos las cargas de los otros». Hay pesos que nadie debería cargar solo: una enfermedad, un duelo, una tentación, una crisis económica. En la iglesia de Cristo, el dolor de uno se vuelve responsabilidad de todos. Y Pablo llama a esto cumplir «la ley de Cristo», que es la ley del amor. Jesús llevó nuestra carga más pesada en la cruz; ahora nos pide que ayudemos a otros con las suyas. Llevar cargas requiere acercarse, escuchar y a veces sacrificar tiempo. Hoy pregúntese a quién puede ayudar. Quizás usted mismo necesita dejar que otros le ayuden con la suya.",
"O versículo anterior fala de restaurar com mansidão o irmão que caiu em alguma falta. Depois Paulo amplia o princípio: «levai as cargas uns dos outros». Há pesos que ninguém deveria carregar sozinho: uma doença, um luto, uma tentação, uma crise financeira. Na igreja de Cristo, a dor de um se torna responsabilidade de todos. E Paulo chama isso de cumprir «a lei de Cristo», que é a lei do amor. Jesus levou o nosso fardo mais pesado na cruz; agora ele nos pede que ajudemos os outros com os seus. Levar fardos exige aproximar-se, ouvir e às vezes sacrificar tempo. Hoje pergunte a si mesmo a quem você pode ajudar. Talvez você mesmo precise deixar que outros o ajudem com o seu.",
"Ofrezca hoy ayuda práctica a alguien que está pasando por una carga pesada.",
"Ofereça hoje ajuda prática a alguém que está passando por um fardo pesado.",
"Señor Jesús, gracias porque llevaste mi carga en la cruz. Dame un corazón dispuesto a ayudar a mis hermanos en sus luchas, y humildad para pedir ayuda cuando la necesite. Que cumplamos juntos la ley del amor. En el nombre de Jesús, amén.",
"Senhor Jesus, obrigado porque levaste o meu fardo na cruz. Dá-me um coração disposto a ajudar meus irmãos em suas lutas, e humildade para pedir ajuda quando eu precisar. Que cumpramos juntos a lei do amor. Em nome de Jesus, amém.")

E("55.3.5", "Salvos por misericordia", "Salvos por misericórdia",
"Pablo le recuerda a Tito cómo éramos antes: insensatos, rebeldes, extraviados. Pero entonces se manifestó la bondad de Dios y su amor por los hombres. Y deja claro el fundamento de la salvación: «no por obras de justicia que nosotros habíamos hecho, mas por su misericordia nos salvó». Después describe cómo lo hizo: «por el lavacro de la regeneración, y de la renovación del Espíritu Santo». Dios no solo perdona, también limpia y hace nacer de nuevo. Y el Espíritu Santo sigue renovando la vida del creyente día tras día. Cuando usted mire a otros que todavía viven lejos de Dios, recuerde que también estuvo allí. Eso le librará del orgullo y le dará compasión. Lo que le salvó fue la misericordia.",
"Paulo lembra a Tito como éramos antes: insensatos, desobedientes, desviados. Mas então se manifestou a bondade de Deus e o seu amor pelos homens. E ele deixa claro o fundamento da salvação: «não pelas obras de justiça que nós tivéssemos feito, mas sim segundo sua misericórdia, ele nos salvou». Depois descreve como ele fez isso: «pelo banho do novo nascimento, e da renovação do Espírito Santo». Deus não apenas perdoa; ele também lava e faz nascer de novo. E o Espírito Santo continua renovando a vida do crente dia após dia. Quando você olhar para outros que ainda vivem longe de Deus, lembre-se de que também esteve lá. Isso o livrará do orgulho e lhe dará compaixão. O que salvou você foi a misericórdia.",
"Trate hoy con especial compasión a alguien que vive lejos de Dios, recordando de dónde le sacó el Señor.",
"Trate hoje com especial compaixão alguém que vive longe de Deus, lembrando de onde o Senhor tirou você.",
"Padre, gracias porque me salvaste por misericordia y no por mis obras. Gracias por el nuevo nacimiento y por la renovación del Espíritu Santo. Líbrame del orgullo y dame compasión por los que aún no te conocen. En el nombre de Jesús, amén.",
"Pai, obrigado porque me salvaste por misericórdia e não por minhas obras. Obrigado pelo novo nascimento e pela renovação do Espírito Santo. Livra-me do orgulho e dá-me compaixão pelos que ainda não te conhecem. Em nome de Jesus, amém.")

E("48.4.32", "Perdonar como fuimos perdonados", "Perdoar como fomos perdoados",
"Los versículos anteriores enumeran lo que el creyente debe quitar de su vida: amargura, enojo, ira, gritería y maledicencia. Pero Pablo no deja un vacío; enseguida indica lo que debe ocupar ese lugar: ser «benignos, misericordiosos, perdonándoos los unos a los otros». La razón es poderosa: «como también Dios os perdonó en Cristo». Cuando nos cuesta perdonar, solemos mirar el tamaño de la ofensa recibida. Pablo nos invita a mirar el tamaño de la ofensa que Dios nos perdonó. Perdonar no significa aprobar el mal ni fingir que no dolió. Significa soltar la deuda y dejar el juicio en manos de Dios. La amargura encadena a quien la guarda. El perdón, en cambio, le deja libre a usted para vivir con un corazón sano.",
"Os versículos anteriores listam o que o crente deve tirar da sua vida: amargura, ira, raiva, gritaria e maledicência. Mas Paulo não deixa um vazio; logo indica o que deve ocupar esse lugar: ser «benignos uns com os outros, misericordiosos, perdoando-vos uns aos outros». A razão é poderosa: «como também Deus vos perdoou em Cristo». Quando temos dificuldade de perdoar, costumamos olhar o tamanho da ofensa recebida. Paulo nos convida a olhar o tamanho da ofensa que Deus nos perdoou. Perdoar não significa aprovar o mal nem fingir que não doeu. Significa soltar a dívida e deixar o julgamento nas mãos de Deus. A amargura acorrenta quem a guarda. O perdão, por outro lado, deixa você livre para viver com um coração saudável.",
"Decida hoy delante de Dios perdonar a una persona que le hirió, y ore por su bien.",
"Decida hoje diante de Deus perdoar uma pessoa que o feriu, e ore pelo bem dela.",
"Padre, me perdonaste mucho más de lo que merecía. Hoy suelto la ofensa que he guardado y entrego a esa persona en las manos de Dios. Quita la amargura de mi corazón y hazme benigno y misericordioso. En el nombre de Jesús, amén.",
"Pai, tu me perdoaste muito mais do que eu merecia. Hoje solto a ofensa que guardei e entrego essa pessoa em tuas mãos. Tira a amargura do meu coração e torna-me benigno e misericordioso. Em nome de Jesus, amém.")

E("46.1.3-4", "Consolados para consolar", "Consolados para consolar",
"Pablo comienza esta carta bendiciendo a Dios en medio de grandes aflicciones. Lo llama «Padre de misericordias, y Dios de toda consolación». No dice que Dios evita todas nuestras tribulaciones, sino que nos consuela «en todas» ellas. Y luego revela un propósito: Dios nos consuela «para que podamos también nosotros consolar a los que están en cualquiera angustia». El consuelo que usted recibe no termina en usted. Las lágrimas que Dios secó en su vida pueden convertirse en una herramienta para secar las de otros. Quien pasó por un duelo, una enfermedad o una traición y fue consolado por Dios entiende mejor a quien sufre lo mismo. Ningún dolor entregado a Dios se desperdicia. Hoy alguien puede necesitar el consuelo que usted ya recibió.",
"Paulo começa esta carta bendizendo a Deus em meio a grandes aflições. Ele o chama de «Pai das misericórdias, e o Deus de toda consolação». Ele não diz que Deus evita todas as nossas tribulações, mas que nos consola «em toda aflição». E depois revela um propósito: Deus nos consola «para que também possamos consolar aos que estiverem em alguma aflição». O consolo que você recebe não termina em você. As lágrimas que Deus enxugou na sua vida podem se tornar uma ferramenta para enxugar as de outros. Quem passou por um luto, uma doença ou uma traição e foi consolado por Deus entende melhor quem sofre o mesmo. Nenhuma dor entregue a Deus é desperdiçada. Hoje alguém pode precisar do consolo que você já recebeu.",
"Comparta con alguien que está sufriendo cómo Dios le consoló en una situación parecida.",
"Compartilhe com alguém que está sofrendo como Deus consolou você numa situação parecida.",
"Padre de misericordias, gracias por consolarme en cada tribulación. No quiero guardar ese consuelo solo para mí. Úsame para acompañar y animar a los que sufren, con el mismo consuelo que recibí de ti. En el nombre de Jesús, amén.",
"Pai das misericórdias, obrigado por me consolar em cada tribulação. Não quero guardar esse consolo só para mim. Usa-me para acompanhar e animar os que sofrem, com o mesmo consolo que recebi de ti. Em nome de Jesus, amém.")

E("55.2.11-13", "La gracia que enseña", "A graça que ensina",
"Pablo presenta la gracia de Dios casi como una maestra. Primero, se manifestó trayendo salvación a todos los hombres. Luego, nos enseña: a renunciar «a la impiedad y a los deseos mundanos» y a vivir «templada, y justa, y píamente» en este tiempo presente. Es decir, con dominio propio hacia uno mismo, con justicia hacia los demás y con devoción hacia Dios. Y todo esto mientras esperamos «aquella esperanza bienaventurada», la manifestación gloriosa de nuestro Señor Jesucristo. La gracia no solo nos perdona el pasado; también forma nuestro presente y orienta nuestro futuro. Si alguien dice que la gracia le permite vivir de cualquier manera, no ha entendido la gracia. Hoy usted puede dejar que ella le enseñe a decir «no» y a decir «sí».",
"Paulo apresenta a graça de Deus quase como uma professora. Primeiro, ela se manifestou trazendo salvação a todos os homens. Depois, ela nos ensina: a renunciar «à irreverência e aos maus desejos mundanos» e a viver de maneira «sóbria, justa e devota» neste tempo presente. Isto é, com domínio próprio em relação a nós mesmos, com justiça para com os outros e com devoção a Deus. E tudo isso enquanto aguardamos «a bem-aventurada esperança», o aparecimento glorioso do nosso Senhor Jesus Cristo. A graça não apenas perdoa o passado; ela também forma o presente e orienta o futuro. Se alguém diz que a graça permite viver de qualquer jeito, não entendeu a graça. Hoje você pode deixar que ela o ensine a dizer «não» e a dizer «sim».",
"Pida a Dios que le muestre un «no» y un «sí» concretos que la gracia le está enseñando hoy.",
"Peça a Deus que lhe mostre um «não» e um «sim» concretos que a graça está ensinando a você hoje.",
"Señor, gracias por la gracia que me salvó y que ahora me enseña. Ayúdame a renunciar a lo que no te agrada y a vivir con sobriedad, justicia y devoción, esperando con gozo la manifestación de Cristo. En el nombre de Jesús, amén.",
"Senhor, obrigado pela graça que me salvou e que agora me ensina. Ajuda-me a renunciar ao que não te agrada e a viver com sobriedade, justiça e devoção, aguardando com alegria a manifestação de Cristo. Em nome de Jesus, amém.")

E("44.15.13", "El Dios de esperanza", "O Deus da esperança",
"Al cerrar la parte central de su carta, Pablo ora por los romanos y llama a Dios con un nombre hermoso: «el Dios de esperanza». Él es la fuente de toda esperanza verdadera. Su oración pide tres cosas: que Dios les llene «de todo gozo y paz», que esto ocurra «creyendo», y que abunden en esperanza «por la virtud del Espíritu Santo». Observe la secuencia: el gozo y la paz llegan cuando confiamos en Dios, y el resultado es una esperanza que desborda. Y no es una esperanza fabricada por pensamiento positivo, sino producida por el poder del Espíritu. Si hoy usted se siente vacío de esperanza, no intente generarla por sí solo. Acérquese al Dios de esperanza y pídale que le llene de nuevo.",
"Ao encerrar a parte central da sua carta, Paulo ora pelos romanos e chama Deus por um nome bonito: «o Deus da esperança». Ele é a fonte de toda esperança verdadeira. Sua oração pede três coisas: que Deus os encha «de toda alegria e paz», que isso aconteça «na fé», e que abundem em esperança «no poder do Espírito Santo». Observe a sequência: a alegria e a paz chegam quando confiamos em Deus, e o resultado é uma esperança que transborda. E não é uma esperança fabricada por pensamento positivo, mas produzida pelo poder do Espírito. Se hoje você se sente vazio de esperança, não tente gerá-la sozinho. Aproxime-se do Deus da esperança e peça que ele o encha de novo.",
"Ore hoy este versículo, palabra por palabra, por usted y por alguien que está desanimado.",
"Ore hoje este versículo, palavra por palavra, por você e por alguém que está desanimado.",
"Dios de esperanza, lléname de todo gozo y paz mientras confío en ti. Por el poder del Espíritu Santo, haz que mi esperanza abunde y desborde hacia los que están desanimados a mi alrededor. En el nombre de Jesús, amén.",
"Deus da esperança, enche-me de toda alegria e paz enquanto confio em ti. Pelo poder do Espírito Santo, faz com que minha esperança abunde e transborde para os que estão desanimados ao meu redor. Em nome de Jesus, amém.")

E("59.4.10", "Administradores de la gracia", "Administradores da graça",
"Pedro escribe que «el fin de todas las cosas se acerca» y por eso exhorta a vivir con seriedad, amor y hospitalidad. Luego habla de los dones: «cada uno según el don que ha recibido, adminístrelo a los otros». Nadie queda fuera de ese «cada uno». Todo creyente ha recibido algo de Dios. Y los dones no son trofeos para exhibir, sino recursos para servir. Pedro nos llama «dispensadores», es decir, administradores. Un administrador cuida bienes que no son suyos y debe rendir cuentas. La «diferente gracia de Dios» se muestra de muchas formas: enseñar, animar, servir, dar, visitar. Hoy usted puede preguntarse no solo qué don tiene, sino a quién está sirviendo con él. Un don guardado no cumple su propósito.",
"Pedro escreve que «o fim de todas as coisas está próximo» e por isso exorta a viver com seriedade, amor e hospitalidade. Depois fala dos dons: «cada um sirva aos outros segundo o dom que recebeu». Ninguém fica fora desse «cada um». Todo crente recebeu algo de Deus. E os dons não são troféus para exibir, mas recursos para servir. Pedro nos chama de «administradores». Um administrador cuida de bens que não são seus e precisa prestar contas. A «variada graça de Deus» se mostra de muitas formas: ensinar, animar, servir, dar, visitar. Hoje você pode se perguntar não apenas qual dom tem, mas a quem está servindo com ele. Um dom guardado não cumpre o seu propósito.",
"Use hoy intencionalmente su don para bendecir a una persona concreta.",
"Use hoje intencionalmente o seu dom para abençoar uma pessoa concreta.",
"Señor, gracias por los dones que me has confiado. No son míos, sino para servir a otros. Ayúdame a administrarlos con fidelidad y humildad, para que en todo sea Dios glorificado por medio de Jesucristo. En el nombre de Jesús, amén.",
"Senhor, obrigado pelos dons que me confiaste. Não são meus, mas para servir aos outros. Ajuda-me a administrá-los com fidelidade e humildade, para que em tudo Deus seja glorificado por meio de Jesus Cristo. Em nome de Jesus, amém.")

E("47.2.20", "Cristo vive en mí", "Cristo vive em mim",
"Pablo explica a los gálatas que no somos justificados por las obras de la ley, sino por la fe en Cristo. Y lo resume con una confesión personal: «con Cristo estoy juntamente crucificado». El viejo Pablo, que confiaba en sus méritos religiosos, murió en la cruz con Cristo. Ahora dice: «vivo, no ya yo, mas vive Cristo en mí». La vida cristiana no es simplemente imitar a Jesús desde afuera, sino dejar que Él viva desde adentro. Y esta vida se sostiene por la fe en el Hijo de Dios, «el cual me amó, y se entregó a sí mismo por mí». Fíjese en lo personal del pronombre: por mí. Usted puede decir lo mismo hoy. Cristo no murió por una multitud anónima; murió por usted.",
"Paulo explica aos gálatas que não somos justificados pelas obras da lei, mas pela fé em Cristo. E resume isso com uma confissão pessoal: «já estou crucificado com Cristo». O velho Paulo, que confiava nos seus méritos religiosos, morreu na cruz com Cristo. Agora ele diz: «estou vivendo não mais eu, mas Cristo vive em mim». A vida cristã não é simplesmente imitar Jesus por fora, mas deixar que ele viva por dentro. E essa vida se sustenta pela fé no Filho de Deus, que me amou e se entregou por mim. Observe como é pessoal o pronome: por mim. Você pode dizer o mesmo hoje. Cristo não morreu por uma multidão anônima; ele morreu por você.",
"Repita hoy varias veces, con fe: «Cristo me amó y se entregó a sí mismo por mí».",
"Repita hoje várias vezes, com fé: «Cristo me amou e se entregou por mim».",
"Señor Jesús, gracias porque me amaste y te entregaste por mí. Mi viejo yo fue crucificado contigo. Vive en mí hoy, en mis decisiones, mis palabras y mis relaciones, para que otros te vean en mi vida. En el nombre de Jesús, amén.",
"Senhor Jesus, obrigado porque me amaste e te entregaste por mim. Meu velho eu foi crucificado contigo. Vive em mim hoje, nas minhas decisões, nas minhas palavras e nos meus relacionamentos, para que outros te vejam na minha vida. Em nome de Jesus, amém.")

E("49.2.3-4", "Mirar también a los otros", "Olhar também para os outros",
"En la iglesia de Filipos había tensiones, y Pablo apunta a la raíz: la contienda y la vanagloria. Su remedio es la humildad, «estimándoos inferiores los unos a los otros». No se trata de despreciarse a uno mismo, sino de valorar sinceramente a los demás. Luego añade: «no mirando cada uno a lo suyo propio, sino cada cual también a lo de los otros». Note la palabra «también»: no está prohibido cuidar lo propio, pero no debemos quedarnos ahí. Los versículos siguientes muestran el ejemplo supremo: Cristo, siendo Dios, se humilló y tomó forma de siervo. Si el Señor de la gloria se inclinó para servir, ¿cómo no hacerlo nosotros? Hoy usted puede mirar a su alrededor y descubrir una necesidad que no es la suya.",
"Na igreja de Filipos havia tensões, e Paulo aponta para a raiz: a rivalidade egoísta e a vanglória. O remédio dele é a humildade, «cada um considere o outro superior a si mesmo». Não se trata de desprezar a si mesmo, mas de valorizar sinceramente os outros. Depois ele acrescenta: «cada um não cuide somente do que é seu; mas cada um cuide também do que é dos outros». Observe a palavra «também»: não é proibido cuidar do que é seu, mas não devemos parar aí. Os versículos seguintes mostram o exemplo supremo: Cristo, sendo Deus, humilhou-se e assumiu a forma de servo. Se o Senhor da glória se inclinou para servir, como não faremos o mesmo? Hoje você pode olhar ao redor e descobrir uma necessidade que não é sua.",
"Atienda hoy una necesidad de otra persona antes de ocuparse de un deseo propio.",
"Atenda hoje uma necessidade de outra pessoa antes de cuidar de um desejo seu.",
"Señor Jesús, siendo Dios te humillaste para servir. Quita de mí la vanagloria y el espíritu de competencia. Dame ojos para ver las necesidades de los demás y un corazón humilde para servirles con alegría. En el nombre de Jesús, amén.",
"Senhor Jesus, sendo Deus, tu te humilhaste para servir. Tira de mim a vanglória e o espírito de competição. Dá-me olhos para ver as necessidades dos outros e um coração humilde para servi-los com alegria. Em nome de Jesus, amém.")

E("59.4.12-13", "No se sorprenda del fuego", "Não estranhe o fogo",
"Pedro escribe a creyentes que comenzaban a sufrir por su fe. Les dice algo que parece duro, pero libera: «no os maravilléis» del fuego de la prueba, «como si alguna cosa peregrina os aconteciese». Muchos se desaniman porque piensan que el sufrimiento significa que Dios los abandonó. Pedro enseña lo contrario: seguir a Cristo incluye participar de sus aflicciones. Pero eso no es todo. Hay una razón para gozarse, porque quienes comparten sus padecimientos también se gozarán «en triunfo» cuando su gloria sea revelada. El dolor de hoy no es la última palabra; es parte del camino que conduce a la gloria. Si usted sufre por hacer lo correcto o por ser fiel a Cristo, no está fuera del plan de Dios. Está siguiendo los pasos de su Señor.",
"Pedro escreve a crentes que começavam a sofrer por causa da fé. Ele diz algo que parece duro, mas liberta: «não estranheis o fogo ardente que vem sobre vós para vos provar, como se algo estranho estivesse vos acontecendo». Muitos desanimam porque pensam que o sofrimento significa que Deus os abandonou. Pedro ensina o contrário: seguir Cristo inclui participar das suas aflições. Mas não é só isso. Há um motivo para se alegrar, porque quem participa dos seus sofrimentos também se alegrará «com júbilo» quando a sua glória for revelada. A dor de hoje não é a última palavra; é parte do caminho que leva à glória. Se você sofre por fazer o que é certo ou por ser fiel a Cristo, não está fora do plano de Deus. Está seguindo os passos do seu Senhor.",
"Ore hoy por los cristianos que sufren persecución en el mundo por causa de su fe.",
"Ore hoje pelos cristãos que sofrem perseguição no mundo por causa da fé.",
"Señor, cuando llegue el fuego de la prueba, no permitas que me sorprenda ni me aparte. Dame gozo al participar de los padecimientos de Cristo y esperanza firme en la revelación de su gloria. En el nombre de Jesús, amén.",
"Senhor, quando vier o fogo da prova, não permitas que eu estranhe nem me afaste. Dá-me alegria em participar dos sofrimentos de Cristo e esperança firme na revelação da sua glória. Em nome de Jesus, amém.")

E("48.1.13-14", "Sellados con el Espíritu", "Selados com o Espírito",
"Pablo describe el camino de la fe: oír «la palabra de verdad, el evangelio de vuestra salud», creer en Cristo y ser sellados «con el Espíritu Santo de la promesa». En aquel tiempo, un sello indicaba propiedad y autenticidad; también protegía un documento o una carga. El Espíritu Santo es la marca de que usted pertenece a Dios. Además, Pablo lo llama «las arras de nuestra herencia». Las arras eran el primer pago que garantizaba que el resto llegaría. La presencia del Espíritu en su vida es una muestra anticipada de todo lo que Dios ha preparado para sus hijos. No está a la espera de una herencia incierta. Dios ya dejó su garantía en usted, y todo esto es «para alabanza de su gloria».",
"Paulo descreve o caminho da fé: ouvir «a palavra da verdade, o evangelho da vossa salvação», crer em Cristo e ser selado com o Espírito Santo da promessa. Naquele tempo, um selo indicava propriedade e autenticidade; também protegia um documento ou uma carga. O Espírito Santo é a marca de que você pertence a Deus. Além disso, Paulo o chama de «garantia da nossa herança». A garantia era o primeiro pagamento que assegurava que o restante viria. A presença do Espírito na sua vida é uma amostra antecipada de tudo o que Deus preparou para os seus filhos. Você não está à espera de uma herança incerta. Deus já deixou a sua garantia em você, e tudo isso é «para louvor da sua glória».",
"Agradezca hoy al Espíritu Santo por su presencia y viva con la seguridad de que pertenece a Dios.",
"Agradeça hoje ao Espírito Santo pela sua presença e viva com a segurança de que você pertence a Deus.",
"Padre, gracias porque me sellaste con el Espíritu Santo de la promesa. Gracias por la garantía de la herencia que me espera. Ayúdame a vivir con la seguridad de que soy de Dios, para alabanza de su gloria. En el nombre de Jesús, amén.",
"Pai, obrigado porque me selaste com o Espírito Santo da promessa. Obrigado pela garantia da herança que me espera. Ajuda-me a viver com a segurança de que sou de Deus, para louvor da sua glória. Em nome de Jesus, amém.")

E("54.1.7", "Poder, amor y dominio propio", "Poder, amor e moderação",
"Pablo escribe a Timoteo, un joven pastor que enfrentaba oposición y que quizás tendía a la timidez. Le pide que avive el fuego del don de Dios que hay en él. Y le recuerda: «no nos ha dado Dios el espíritu de temor». El miedo que paraliza no viene de Dios. En cambio, Él nos da un espíritu «de fortaleza, y de amor, y de templanza». Fortaleza para enfrentar lo que nos toca; amor para que esa fuerza no se vuelva dureza; y templanza, es decir, una mente sobria y equilibrada. El versículo siguiente invita a no avergonzarse del testimonio del Señor. Si hoy usted tiene que dar un paso que le asusta en el servicio o en el testimonio, recuerde qué clase de espíritu ha recibido.",
"Paulo escreve a Timóteo, um jovem pastor que enfrentava oposição e que talvez tendesse à timidez. Ele pede que Timóteo reavive o dom de Deus que há nele. E lembra: «Deus não nos deu espírito de medo». O medo que paralisa não vem de Deus. Em vez disso, ele nos dá um espírito «de força, de amor, e de moderação». Força para enfrentar o que nos cabe; amor para que essa força não se torne dureza; e moderação, isto é, uma mente sóbria e equilibrada. O versículo seguinte convida a não se envergonhar do testemunho do Senhor. Se hoje você precisa dar um passo que o assusta no serviço ou no testemunho, lembre-se de que tipo de espírito você recebeu.",
"Dé hoy, con valor y amor, un paso de obediencia que ha estado postergando por temor.",
"Dê hoje, com coragem e amor, um passo de obediência que você vem adiando por medo.",
"Señor, rechazo el espíritu de temor que me paraliza. Gracias porque me has dado fortaleza, amor y dominio propio. Aviva el don que pusiste en mí y dame valor para servir y testificar sin avergonzarme. En el nombre de Jesús, amén.",
"Senhor, rejeito o espírito de medo que me paralisa. Obrigado porque me deste força, amor e moderação. Reaviva o dom que puseste em mim e dá-me coragem para servir e testemunhar sem me envergonhar. Em nome de Jesus, amém.")

E("44.8.38-39", "Nada nos separará", "Nada nos separará",
"Romanos ocho termina con una de las declaraciones más firmes de toda la Biblia. Pablo acaba de preguntar quién nos separará del amor de Cristo: ¿tribulación, angustia, persecución, hambre, peligro? Y responde con plena convicción: «estoy cierto». Luego recorre todo lo que podría amenazarnos: la muerte y la vida, los ángeles y los poderes, lo presente y lo por venir, lo alto y lo bajo. Nada de eso, ni «ninguna criatura nos podrá apartar del amor de Dios, que es en Cristo Jesús Señor nuestro». Fíjese que la seguridad no está en la fuerza de nuestro amor por Dios, sino en la firmeza de su amor por nosotros. Hoy usted puede enfrentar cualquier temor sabiendo que nada en el universo puede cortar ese lazo.",
"Romanos oito termina com uma das declarações mais firmes de toda a Bíblia. Paulo acaba de perguntar quem nos separará do amor de Cristo: tribulação, angústia, perseguição, fome, perigo? E responde com plena convicção: «tenho certeza». Depois percorre tudo o que poderia nos ameaçar: a morte e a vida, os anjos e os poderes, o presente e o futuro, a altura e a profundeza. Nada disso, nem «qualquer outra criatura poderá nos separar do amor de Deus, que está em Cristo Jesus, nosso Senhor». Observe que a segurança não está na força do nosso amor por Deus, mas na firmeza do amor dele por nós. Hoje você pode enfrentar qualquer medo sabendo que nada no universo pode cortar esse laço.",
"Nombre su mayor temor actual y declare delante de Dios que ni eso puede separarle de su amor.",
"Dê nome ao seu maior medo atual e declare diante de Deus que nem isso pode separá-lo do amor dele.",
"Padre, gracias porque nada puede separarme del amor de Dios en Cristo Jesús. Ni la muerte, ni la vida, ni lo presente, ni lo por venir. Afirma mi corazón en esta certeza cuando tenga miedo. En el nombre de Jesús, amén.",
"Pai, obrigado porque nada pode me separar do amor que tens por mim em Cristo Jesus. Nem a morte, nem a vida, nem o presente, nem o futuro. Firma meu coração nesta certeza quando eu tiver medo. Em nome de Jesus, amém.")

E("58.1.19", "Pronto para oír", "Pronto para ouvir",
"Santiago da un consejo muy práctico: «todo hombre sea pronto para oír, tardío para hablar, tardío para airarse». Muchas veces hacemos lo contrario: respondemos antes de escuchar, hablamos sin pensar y nos enojamos con rapidez. El versículo siguiente explica por qué es tan importante: «la ira del hombre no obra la justicia de Dios». Y en el contexto, Santiago habla de recibir con mansedumbre la palabra de Dios. Quien aprende a escuchar a Dios con humildad aprende también a escuchar a las personas. Escuchar bien es una forma de amar. Le muestra al otro que le importa. En casa, en la iglesia o en el trabajo, usted puede evitar muchas heridas si se toma unos segundos antes de responder. El silencio a tiempo también es sabiduría.",
"Tiago dá um conselho muito prático: «toda pessoa seja pronta para ouvir, tardia para falar, tardia para se irar». Muitas vezes fazemos o contrário: respondemos antes de ouvir, falamos sem pensar e nos iramos com rapidez. O versículo seguinte explica por que isso é tão importante: a ira do homem não produz a justiça de Deus. E no contexto, Tiago fala de receber com mansidão a palavra de Deus. Quem aprende a ouvir a Deus com humildade aprende também a ouvir as pessoas. Ouvir bem é uma forma de amar. Mostra ao outro que ele importa. Em casa, na igreja ou no trabalho, você pode evitar muitas feridas se tomar alguns segundos antes de responder. O silêncio na hora certa também é sabedoria.",
"En su próxima conversación difícil, escuche hasta el final antes de responder.",
"Na sua próxima conversa difícil, ouça até o fim antes de responder.",
"Señor, enséñame a escuchar más y a hablar menos. Refrena mi lengua y guarda mi corazón de la ira. Que mis palabras sean pocas, sabias y llenas de gracia, y que mi trato muestre el amor de Cristo. En el nombre de Jesús, amén.",
"Senhor, ensina-me a ouvir mais e a falar menos. Refreia minha língua e guarda meu coração da ira. Que minhas palavras sejam poucas, sábias e cheias de graça, e que meu trato mostre o amor de Cristo. Em nome de Jesus, amém.")

E("57.12.1-2", "Correr con los ojos en Jesús", "Correr com os olhos em Jesus",
"El capítulo once de Hebreos presenta a los héroes de la fe. Ahora el autor los describe como «una tan grande nube de testigos» que nos rodea, ejemplos de que es posible terminar la carrera. Luego da tres instrucciones. Primero, dejar todo peso y el pecado que nos enreda; un corredor no lleva cargas innecesarias. Segundo, correr «con paciencia», porque la vida cristiana es una carrera de resistencia, no de velocidad. Tercero, y lo más importante, correr con los ojos puestos «en Jesús, el autor y consumador de la fe». Él comenzó la fe en usted y la llevará a término. Él mismo soportó la cruz por el gozo que tenía delante. Cuando se canse, no mire solo el camino ni a los demás corredores; mire a Jesús.",
"O capítulo onze de Hebreus apresenta os heróis da fé. Agora o autor os descreve como «uma tão grande nuvem de testemunhas» que nos rodeia, exemplos de que é possível terminar a corrida. Depois dá três instruções. Primeiro, deixar toda sobrecarga e o pecado que nos enreda; um corredor não carrega pesos desnecessários. Segundo, correr com perseverança, porque a vida cristã é uma corrida de resistência, não de velocidade. Terceiro, e mais importante, correr «olhando para Jesus, Autor e aperfeiçoador da fé». Ele começou a fé em você e a levará até o fim. Ele mesmo suportou a cruz pela alegria que lhe estava proposta. Quando você se cansar, não olhe apenas para o caminho nem para os outros corredores; olhe para Jesus.",
"Identifique un peso que le está frenando en su vida espiritual y entréguelo hoy a Dios.",
"Identifique um peso que está atrasando a sua vida espiritual e entregue-o hoje a Deus.",
"Señor Jesús, autor y consumador de mi fe, ayúdame a dejar todo peso y todo pecado que me enreda. Dame paciencia para correr hasta el final y mantén mis ojos fijos en ti. En el nombre de Jesús, amén.",
"Senhor Jesus, autor e aperfeiçoador da minha fé, ajuda-me a deixar todo peso e todo pecado que me enreda. Dá-me perseverança para correr até o fim e mantém meus olhos fixos em ti. Em nome de Jesus, amém.")

E("46.3.18", "De gloria en gloria", "De glória em glória",
"Pablo compara el antiguo pacto con el nuevo. Moisés cubría su rostro con un velo después de estar con Dios. Pero en Cristo el velo es quitado. Ahora, «nosotros todos, mirando a cara descubierta como en un espejo la gloria del Señor, somos transformados de gloria en gloria». La transformación del creyente es un proceso continuo, no un cambio instantáneo y terminado. Y sucede mientras contemplamos al Señor: en su Palabra, en la oración, en la adoración. Nos parecemos a lo que miramos con constancia. Además, esta obra no depende de nuestro esfuerzo humano, sino que es «por el Espíritu del Señor». Si hoy usted se siente lejos de lo que quisiera ser, no se rinda. Siga mirando a Cristo; el Espíritu está trabajando.",
"Paulo compara a antiga aliança com a nova. Moisés cobria o rosto com um véu depois de estar com Deus. Mas em Cristo o véu é retirado. Agora, «todos nós, com o rosto descoberto, refletindo como que um espelho a glória do Senhor, somos transformados de glória em glória». A transformação do crente é um processo contínuo, não uma mudança instantânea e acabada. E ela acontece enquanto contemplamos o Senhor: na sua Palavra, na oração, na adoração. Nós nos parecemos com aquilo que olhamos com constância. Além disso, essa obra não depende do nosso esforço humano, mas vem do Espírito do Senhor. Se hoje você se sente longe do que gostaria de ser, não desista. Continue olhando para Cristo; o Espírito está trabalhando.",
"Dedique hoy un tiempo sin distracciones a contemplar a Cristo en un pasaje de los Evangelios.",
"Dedique hoje um tempo sem distrações para contemplar Cristo em uma passagem dos Evangelhos.",
"Señor, quita todo velo de mi corazón para que pueda contemplar la gloria de Cristo. Espíritu Santo, sigue transformándome de gloria en gloria, aunque el proceso sea lento. Hazme cada día más parecido a Jesús. En el nombre de Jesús, amén.",
"Senhor, tira todo véu do meu coração para que eu possa contemplar a glória de Cristo. Espírito Santo, continua me transformando de glória em glória, mesmo que o processo seja lento. Torna-me a cada dia mais parecido com Jesus. Em nome de Jesus, amém.")
# --- Días 347-365 ---
E("48.6.18", "Orar en todo tiempo", "Orar em todo tempo",
"Después de describir la armadura de Dios, Pablo no termina con una pieza más, sino con una actitud que lo envuelve todo: «orando en todo tiempo con toda deprecación y súplica en el Espíritu». La armadura no funciona sin oración. Un soldado bien equipado pero sin comunicación con su comandante está en peligro. Pablo pide orar en todo tiempo, no solo en las crisis; orar en el Espíritu, dependiendo de su dirección; velar con perseverancia; y hacerlo «por todos los santos». La batalla espiritual no es individual: oramos unos por otros. En el versículo siguiente, el mismo Pablo pide oración para hablar con denuedo. Si un apóstol necesitaba que oraran por él, cuánto más nosotros. Hoy usted puede ser el que sostiene en oración a un hermano en la batalla.",
"Depois de descrever a armadura de Deus, Paulo não termina com mais uma peça, mas com uma atitude que envolve tudo: «orando em todo tempo com toda oração e súplica no Espírito». A armadura não funciona sem oração. Um soldado bem equipado, mas sem comunicação com o seu comandante, está em perigo. Paulo pede que oremos em todo tempo, não apenas nas crises; que oremos no Espírito, dependendo da sua direção; que vigiemos com perseverança; e que façamos isso «por todos os santos». A batalha espiritual não é individual: oramos uns pelos outros. No versículo seguinte, o próprio Paulo pede oração para falar com ousadia. Se um apóstolo precisava que orassem por ele, quanto mais nós. Hoje você pode ser quem sustenta em oração um irmão na batalha.",
"Escriba los nombres de tres hermanos y ore por cada uno de ellos durante esta semana.",
"Escreva o nome de três irmãos e ore por cada um deles durante esta semana.",
"Señor, enséñame a orar en todo tiempo y no solo en la necesidad. Guíame por el Espíritu en mis oraciones. Pongo delante de ti a mis hermanos que están en la batalla; fortalécelos y dales valor. En el nombre de Jesús, amén.",
"Senhor, ensina-me a orar em todo tempo e não só na necessidade. Guia-me pelo Espírito nas minhas orações. Coloco diante de ti meus irmãos que estão na batalha; fortalece-os e dá-lhes coragem. Em nome de Jesus, amém.")

E("47.6.9", "No se canse de hacer bien", "Não desista de fazer o bem",
"Pablo acaba de recordar un principio: lo que el hombre siembra, eso también segará. Quien siembra para el Espíritu, del Espíritu segará vida eterna. Luego anima: «no nos cansemos, pues, de hacer bien». Pablo sabía que el cansancio es real. Hacer el bien muchas veces no es reconocido, a veces es malinterpretado, y los resultados tardan. Pero la promesa es segura: «a su tiempo segaremos». No dice cuándo, pero dice que llegará. La condición es no desmayar, no abandonar a mitad del camino. El agricultor no ve la cosecha el día que siembra. Quizás usted lleva tiempo sirviendo, ayudando u orando por alguien sin ver fruto. Este versículo es para hoy: siga sembrando. El tiempo de la cosecha está en manos de Dios.",
"Paulo acaba de lembrar um princípio: aquilo que o homem semear, isso também colherá. Quem semeia para o Espírito, do Espírito colherá vida eterna. Depois ele anima: «não cansemos de fazer o bem». Paulo sabia que o cansaço é real. Fazer o bem muitas vezes não é reconhecido, às vezes é mal interpretado, e os resultados demoram. Mas a promessa é segura: «no tempo devido colheremos». Ele não diz quando, mas diz que virá. A condição é não desistir, não abandonar no meio do caminho. O agricultor não vê a colheita no dia em que semeia. Talvez você esteja há muito tempo servindo, ajudando ou orando por alguém sem ver fruto. Este versículo é para hoje: continue semeando. O tempo da colheita está nas mãos de Deus.",
"Continúe hoy con fidelidad una buena obra que ha estado a punto de abandonar.",
"Continue hoje com fidelidade uma boa obra que você esteve a ponto de abandonar.",
"Señor, a veces me canso de hacer el bien sin ver resultados. Renueva mis fuerzas y mi ánimo. Ayúdame a seguir sembrando con fe, confiando en que a su tiempo veré la cosecha que prometiste. En el nombre de Jesús, amén.",
"Senhor, às vezes me canso de fazer o bem sem ver resultados. Renova minhas forças e meu ânimo. Ajuda-me a continuar semeando com fé, confiando que no tempo certo verei a colheita que prometeste. Em nome de Jesus, amém.")

E("61.4.18", "El amor echa fuera el temor", "O amor lança fora o medo",
"Juan escribe que Dios es amor y que quien permanece en el amor permanece en Dios. En ese contexto, habla del día del juicio y afirma que podemos tener confianza en ese día. Luego explica: «en amor no hay temor; mas el perfecto amor echa fuera el temor». Aquí se refiere especialmente al temor al castigo, porque «el temor tiene pena». Quien todavía vive con terror de ser rechazado por Dios no ha comprendido del todo su amor. Esto no elimina el temor reverente, que es respeto y adoración. Pero sí quita el miedo del esclavo que espera el látigo. El versículo diecinueve completa: nosotros le amamos porque Él nos amó primero. Cuanto más usted conozca el amor de Dios, menos espacio tendrá el miedo en su corazón.",
"João escreve que Deus é amor e que quem permanece no amor permanece em Deus. Nesse contexto, ele fala do dia do juízo e afirma que podemos ter confiança nesse dia. Depois explica: «no amor não há medo; pelo contrário, o perfeito amor expulsa o medo». Aqui ele se refere especialmente ao medo do castigo, «pois o medo envolve castigo». Quem ainda vive com pavor de ser rejeitado por Deus não compreendeu totalmente o seu amor. Isso não elimina o temor reverente, que é respeito e adoração. Mas tira o medo do escravo que espera o chicote. O versículo dezenove completa: nós o amamos porque ele nos amou primeiro. Quanto mais você conhecer o amor de Deus, menos espaço o medo terá no seu coração.",
"Lea hoy el capítulo cuatro de Primera de Juan y anote todo lo que dice sobre el amor de Dios.",
"Leia hoje o capítulo quatro de Primeira João e anote tudo o que ele diz sobre o amor de Deus.",
"Padre, gracias porque me amaste primero. Echa fuera de mi corazón el miedo al castigo y al rechazo. Perfecciona en mí el amor, para que viva con confianza delante de ti y ame a los demás sin temor. En el nombre de Jesús, amén.",
"Pai, obrigado porque me amaste primeiro. Lança fora do meu coração o medo do castigo e da rejeição. Aperfeiçoa em mim o teu amor, para que eu viva com confiança diante de ti e ame os outros sem medo. Em nome de Jesus, amém.")

E("49.4.6-7", "Cambiar afán por oración", "Trocar ansiedade por oração",
"Pablo, desde la cárcel, da una instrucción clara: «por nada estéis afanosos». No dice que los problemas no existan, sino que no debemos dejar que la ansiedad gobierne el corazón. ¿Qué hacer entonces con las preocupaciones? Convertirlas en oración: «sean notorias vuestras peticiones delante de Dios en toda oración y ruego, con hacimiento de gracias». Note el ingrediente de la gratitud: recordar lo que Dios ya hizo fortalece la fe para lo que todavía pedimos. Y la promesa no es que todo se resolverá de inmediato, sino que «la paz de Dios, que sobrepuja todo entendimiento», guardará el corazón y la mente. Es una paz que no se explica por las circunstancias. Hoy usted puede tomar cada preocupación y transformarla, una por una, en una petición acompañada de gratitud.",
"Paulo, da prisão, dá uma instrução clara: «não estejais ansiosos por coisa alguma». Ele não diz que os problemas não existem, mas que não devemos deixar a ansiedade governar o coração. O que fazer, então, com as preocupações? Transformá-las em oração: «em tudo, por meio de orações e súplicas com ações de gratidão, sejam os vossos pedidos conhecidos por Deus». Observe o ingrediente da gratidão: lembrar o que Deus já fez fortalece a fé para o que ainda pedimos. E a promessa não é que tudo se resolverá imediatamente, mas que «a paz de Deus, que excede todo entendimento», guardará o coração e a mente. É uma paz que não se explica pelas circunstâncias. Hoje você pode pegar cada preocupação e transformá-la, uma por uma, em um pedido acompanhado de gratidão.",
"Escriba sus tres mayores preocupaciones y conviértalas en oraciones, agregando una gratitud a cada una.",
"Escreva suas três maiores preocupações e transforme-as em orações, acrescentando uma gratidão a cada uma.",
"Señor, te entrego mis preocupaciones una por una. Gracias por todo lo que ya hiciste por mí. Guarda mi corazón y mis pensamientos con la paz que sobrepasa todo entendimiento, en Cristo Jesús. En el nombre de Jesús, amén.",
"Senhor, eu te entrego minhas preocupações uma por uma. Obrigado por tudo o que já fizeste por mim. Guarda meu coração e meus pensamentos com a paz que excede todo entendimento, em Cristo Jesus. Em nome de Jesus, amém.")

E("51.5.23-24", "Fiel es el que llama", "Fiel é quem chama",
"Pablo termina su primera carta a los tesalonicenses con una oración: que el Dios de paz los santifique «en todo», y que su espíritu, alma y cuerpo sean guardados sin reprensión para la venida de Cristo. Es una meta alta: toda la persona apartada para Dios. Al leerla, uno podría pensar: «¿Cómo podré yo lograr algo así?». Por eso el versículo siguiente trae el alivio: «Fiel es el que os ha llamado; el cual también lo hará». La santificación no depende solo de nuestra fuerza. El mismo Dios que le llamó es quien completará la obra. Usted participa con obediencia, pero quien sostiene el proceso es Él. Cuando vea sus fallas, no se desespere. Mire la fidelidad de Aquel que prometió terminar lo que comenzó.",
"Paulo termina sua primeira carta aos tessalonicenses com uma oração: que o Deus da paz os santifique «em tudo», e que seu espírito, alma e corpo sejam preservados irrepreensíveis para a vinda de Cristo. É uma meta alta: a pessoa inteira separada para Deus. Ao ler isso, alguém poderia pensar: «Como eu vou conseguir algo assim?». Por isso o versículo seguinte traz o alívio: «Fiel é aquele que vos chama, e ele também o fará». A santificação não depende apenas da nossa força. O mesmo Deus que chamou você é quem completará a obra. Você participa com obediência, mas quem sustenta o processo é ele. Quando você olhar para as suas falhas, não se desespere. Olhe para a fidelidade daquele que prometeu terminar o que começou.",
"Entregue hoy a Dios un área de su vida que todavía necesita ser santificada, confiando en su fidelidad.",
"Entregue hoje a Deus uma área da sua vida que ainda precisa ser santificada, confiando na fidelidade dele.",
"Dios de paz, santifícame por completo: mi espíritu, mi alma y mi cuerpo. Reconozco que no puedo hacerlo solo. Gracias porque eres fiel y completarás la obra que comenzaste en mí hasta la venida de Cristo. En el nombre de Jesús, amén.",
"Deus da paz, santifica-me por completo: meu espírito, minha alma e meu corpo. Reconheço que não consigo fazer isso sozinho. Obrigado porque és fiel e completarás a obra que começaste em mim até a vinda de Cristo. Em nome de Jesus, amém.")

E("50.3.23", "Trabajar como para el Señor", "Trabalhar como para o Senhor",
"Pablo da esta instrucción en un contexto muy concreto: se dirige a siervos que trabajaban para amos terrenales. Les dice: «todo lo que hagáis, hacedlo de ánimo, como al Señor, y no a los hombres». El versículo siguiente da la razón: del Señor recibirán la recompensa, porque «a Cristo el Señor servís». Esto transforma el trabajo diario. Usted puede estar cocinando, manejando, vendiendo, limpiando o enseñando. Si lo hace para Cristo, ese trabajo se convierte en un acto de adoración. No importa si el jefe lo ve o si los clientes lo agradecen. La calidad, la honestidad y el buen ánimo del creyente no dependen de quién lo observa, sino de para quién trabaja. Hoy, cada tarea puede ser una ofrenda.",
"Paulo dá esta instrução num contexto muito concreto: ele se dirige a servos que trabalhavam para senhores terrenos. E diz: «tudo quanto fizerdes, fazei de coração, como que para o Senhor, e não para as pessoas». O versículo seguinte dá a razão: do Senhor receberão a recompensa, porque é a Cristo, o Senhor, que servem. Isso transforma o trabalho diário. Você pode estar cozinhando, dirigindo, vendendo, limpando ou ensinando. Se faz isso para Cristo, esse trabalho se torna um ato de adoração. Não importa se o chefe vê ou se os clientes agradecem. A qualidade, a honestidade e o bom ânimo do crente não dependem de quem observa, mas de para quem ele trabalha. Hoje, cada tarefa pode ser uma oferta.",
"Antes de comenzar su trabajo hoy, dedíquelo en oración al Señor y hágalo con excelencia.",
"Antes de começar o seu trabalho hoje, dedique-o em oração ao Senhor e faça-o com excelência.",
"Señor, hoy dedico mi trabajo a ti. Ayúdame a hacerlo con ánimo, honestidad y excelencia, aunque nadie lo vea. Que mis tareas diarias sean una ofrenda agradable y un testimonio de Cristo. En el nombre de Jesús, amén.",
"Senhor, hoje dedico meu trabalho a ti. Ajuda-me a fazê-lo de coração, com honestidade e excelência, mesmo que ninguém veja. Que minhas tarefas diárias sejam uma oferta agradável e um testemunho de Cristo. Em nome de Jesus, amém.")

E("48.3.20-21", "Mucho más abundantemente", "Muito mais abundantemente",
"Pablo acaba de orar para que los efesios conozcan el amor de Cristo, que excede todo conocimiento. Y entonces termina con una alabanza: Dios «es poderoso para hacer todas las cosas mucho más abundantemente de lo que pedimos o entendemos». Nuestras oraciones tienen límites; nuestra imaginación también. Pero Dios no está limitado por lo que podemos pedir ni por lo que alcanzamos a pensar. Y fíjese dónde actúa ese poder: «por la potencia que obra en nosotros». No es solo un poder lejano, sino uno que ya está trabajando en sus hijos por el Espíritu. El propósito final no es nuestra comodidad, sino «a Él sea gloria en la iglesia por Cristo Jesús». Hoy usted puede orar con fe, sabiendo que Dios es más grande que sus peticiones.",
"Paulo acaba de orar para que os efésios conheçam o amor de Cristo, que excede todo entendimento. E então termina com um louvor: Deus «é poderoso para fazer tudo muito mais abundantemente do que pedimos ou pensamos». Nossas orações têm limites; nossa imaginação também. Mas Deus não está limitado pelo que podemos pedir nem pelo que conseguimos pensar. E observe onde esse poder age: «segundo o poder que opera em nós». Não é apenas um poder distante, mas um poder que já está trabalhando em seus filhos pelo Espírito. O propósito final não é o nosso conforto, mas «a ele seja a glória na Igreja, e em Cristo Jesus». Hoje você pode orar com fé, sabendo que Deus é maior do que os seus pedidos.",
"Presente hoy a Dios una petición que le parecía demasiado grande, y termine su oración dándole gloria.",
"Apresente hoje a Deus um pedido que lhe parecia grande demais, e termine sua oração dando glória a ele.",
"Señor, eres poderoso para hacer mucho más de lo que pido o entiendo. Perdona mi pequeña fe. Obra en mí y en la iglesia con el poder del Espíritu, y que toda la gloria sea para Dios en la iglesia por Cristo Jesús. En el nombre de Jesús, amén.",
"Senhor, tu és poderoso para fazer muito mais do que peço ou penso. Perdoa minha pequena fé. Age em mim e na igreja com o poder do Espírito, e que toda a glória seja para Deus na Igreja, por Cristo Jesus. Em nome de Jesus, amém.")

E("54.4.7-8", "Terminar bien la carrera", "Terminar bem a corrida",
"Esta es una de las últimas palabras de Pablo antes de su muerte. Desde la prisión en Roma, mira hacia atrás y puede decir: «he peleado la buena batalla, he acabado la carrera, he guardado la fe». No dice que fue perfecto ni que no tuvo luchas, sino que fue fiel hasta el final. Y luego mira hacia adelante: le espera «la corona de justicia», que el Señor, juez justo, le dará en aquel día. Pero añade algo que nos incluye: no solo a él, «sino también a todos los que aman su venida». A medida que el año se acerca a su fin, es buen momento para preguntarse cómo está su carrera. No importa cómo comenzó, sino cómo va a terminar. Lo que Dios busca es fidelidad.",
"Estas são algumas das últimas palavras de Paulo antes da sua morte. Da prisão em Roma, ele olha para trás e pode dizer: «lutei a boa luta, terminei a carreira, guardei a fé». Ele não diz que foi perfeito nem que não teve lutas, mas que foi fiel até o fim. E então olha para frente: espera-o «a coroa da justiça», que o Senhor, o justo Juiz, lhe dará naquele dia. Mas acrescenta algo que nos inclui: não somente a ele, mas também a todos os que amam a sua vinda. À medida que o ano se aproxima do fim, é um bom momento para perguntar como está a sua corrida. Não importa como você começou, mas como vai terminar. O que Deus procura é fidelidade.",
"Haga hoy una pausa para evaluar su vida espiritual de este año y anote un compromiso de fidelidad.",
"Faça hoje uma pausa para avaliar a sua vida espiritual deste ano e anote um compromisso de fidelidade.",
"Señor, quiero pelear la buena batalla, acabar la carrera y guardar la fe. Perdona mis tropiezos de este año y dame fuerzas para ser fiel hasta el final. Haz que ame cada día más la venida de Cristo. En el nombre de Jesús, amén.",
"Senhor, quero combater o bom combate, terminar a carreira e guardar a fé. Perdoa meus tropeços deste ano e dá-me forças para ser fiel até o fim. Faz com que eu ame cada dia mais a vinda de Cristo. Em nome de Jesus, amém.")

E("65.21.1-3", "Dios morará con su pueblo", "Deus habitará com seu povo",
"Después de las visiones de juicio, Juan contempla algo glorioso: «un cielo nuevo, y una tierra nueva». La primera creación, marcada por el pecado, da lugar a una nueva. Luego ve la santa ciudad, la nueva Jerusalén, descender del cielo «como una esposa ataviada para su marido». Y escucha el anuncio central: «He aquí el tabernáculo de Dios con los hombres, y morará con ellos». El mayor tesoro del cielo no son las calles de oro, sino la presencia de Dios. Desde el Edén, Dios ha buscado habitar con su pueblo; en el tabernáculo, en el templo, en Cristo, en la iglesia por su Espíritu. En la nueva creación, esa comunión será plena y sin interrupción. Esta es la esperanza que sostiene al creyente: estar con Dios para siempre.",
"Depois das visões de juízo, João contempla algo glorioso: «um novo céu e uma nova terra». A primeira criação, marcada pelo pecado, dá lugar a uma nova. Depois ele vê a cidade santa, a nova Jerusalém, descendo do céu «preparada como noiva, adornada para seu marido». E ouve o anúncio central: «Eis que o tabernáculo de Deus está com os homens, e com eles habitará». O maior tesouro do céu não são as ruas de ouro, mas a presença de Deus. Desde o Éden, Deus tem buscado habitar com o seu povo: no tabernáculo, no templo, em Cristo, na igreja pelo seu Espírito. Na nova criação, essa comunhão será plena e sem interrupção. Essa é a esperança que sustenta o crente: estar com Deus para sempre.",
"Dedique hoy un momento a imaginar con la Biblia la nueva creación y adore a Dios por esa esperanza.",
"Dedique hoje um momento para imaginar com a Bíblia a nova criação e adore a Deus por essa esperança.",
"Señor, gracias por la promesa de un cielo nuevo y una tierra nueva, donde morarás con los tuyos. Mientras espero ese día, ayúdame a disfrutar desde ahora de la presencia de Dios y a prepararme para estar siempre con Él. En el nombre de Jesús, amén.",
"Senhor, obrigado pela promessa de um novo céu e uma nova terra, onde habitarás com o teu povo. Enquanto espero esse dia, ajuda-me a desfrutar desde agora da tua presença e a me preparar para estar sempre contigo. Em nome de Jesus, amém.")

E("64.1.24-25", "Poderoso para guardarle", "Poderoso para guardar você",
"La carta de Judas advierte sobre falsos maestros y tiempos difíciles. Pero termina con una de las alabanzas más hermosas del Nuevo Testamento. Dios es «poderoso para guardaros sin caída». Usted no se sostiene en la fe solo por su propia fuerza; Dios le guarda. Y no solo eso: Él puede presentarle «delante de su gloria irreprensibles, con grande alegría». Imagine ese momento: estar ante la gloria de Dios, no con vergüenza, sino con gozo, porque Cristo le limpió por completo. Por eso Judas concluye adorando: al único Dios sabio, nuestro Salvador, sea gloria y majestad, imperio y potencia, ahora y siempre. Cuando mire el camino que aún falta y sienta temor de caer, recuerde quién le guarda. Su seguridad descansa en el poder de Dios.",
"A carta de Judas adverte sobre falsos mestres e tempos difíceis. Mas termina com um dos louvores mais bonitos do Novo Testamento. Deus é «poderoso para vos guardar de tropeçar». Você não se mantém na fé apenas pela sua própria força; Deus guarda você. E não só isso: ele pode apresentar você «irrepreensível com alegria diante de sua glória». Imagine esse momento: estar diante da glória de Deus, não com vergonha, mas com alegria, porque Cristo o purificou por completo. Por isso Judas conclui adorando: ao único Deus, nosso Salvador, seja a glória e majestade, poder e autoridade, agora e para sempre. Quando você olhar o caminho que ainda falta e tiver medo de cair, lembre-se de quem o guarda. A sua segurança descansa no poder de Deus.",
"Lea en voz alta estos dos versículos como una alabanza personal a Dios al comenzar el día.",
"Leia em voz alta estes dois versículos como um louvor pessoal a Deus ao começar o dia.",
"Dios y Salvador mío, gracias porque eres poderoso para guardarme sin caída. Cuando tema tropezar, sostenme. A ti sea la gloria, la majestad, el imperio y la potencia, ahora y por todos los siglos. En el nombre de Jesús, amén.",
"Deus e Salvador meu, obrigado porque és poderoso para me guardar de tropeçar. Quando eu tiver medo de cair, sustenta-me. A ti seja a glória, a majestade, o poder e a autoridade, agora e para todo o sempre. Em nome de Jesus, amém.")

E("46.9.15", "Gracias por el don inefable", "Graças pelo dom indescritível",
"En los capítulos ocho y nueve, Pablo anima a los corintios a participar en una ofrenda para los hermanos pobres de Jerusalén. Habla de sembrar con generosidad y de dar con alegría. Pero al final de todo, eleva la mirada hacia el mayor de todos los regalos: «Gracias a Dios por su don inefable». Inefable es aquello que no se puede expresar con palabras. Todo lo que damos es apenas una respuesta a lo que Dios nos dio primero: a su propio Hijo. En estos días de fin de año, cuando se habla tanto de regalos, este versículo pone las cosas en su lugar. Ningún regalo se compara con Cristo. La gratitud por ese don es la fuente de toda generosidad verdadera. Hoy usted puede dar gracias por Él.",
"Nos capítulos oito e nove, Paulo anima os coríntios a participar de uma oferta para os irmãos pobres de Jerusalém. Ele fala de semear com generosidade e de dar com alegria. Mas, no fim de tudo, eleva o olhar para o maior de todos os presentes: «graças a Deus por seu dom indescritível». Indescritível é aquilo que não se pode expressar com palavras. Tudo o que damos é apenas uma resposta ao que Deus nos deu primeiro: o seu próprio Filho. Nestes dias de fim de ano, quando se fala tanto de presentes, este versículo coloca as coisas no lugar. Nenhum presente se compara a Cristo. A gratidão por esse dom é a fonte de toda generosidade verdadeira. Hoje você pode dar graças por ele.",
"Haga hoy un acto de generosidad para alguien necesitado, como respuesta de gratitud por el don de Cristo.",
"Faça hoje um ato de generosidade para alguém necessitado, como resposta de gratidão pelo dom de Cristo.",
"Padre, gracias por el don inefable de Jesucristo. No tengo palabras suficientes para agradecer tanto amor. Que mi gratitud se convierta en generosidad hacia los que necesitan, para la gloria de Dios. En el nombre de Jesús, amén.",
"Pai, obrigado pelo dom indescritível de Jesus Cristo. Não tenho palavras suficientes para agradecer tanto amor. Que minha gratidão se transforme em generosidade para com os necessitados, para a glória de Deus. Em nome de Jesus, amém.")

E("50.3.15", "La paz gobierne su corazón", "Que a paz governe seu coração",
"Pablo describe la vida nueva del creyente en comunidad. Después de hablar de perdón y amor, dice: «la paz de Dios gobierne en vuestros corazones». La palabra gobernar evoca a un árbitro que decide en un juego. Cuando surgen conflictos, emociones fuertes o decisiones difíciles, la paz de Cristo debe tener la última palabra en su interior. Y añade que fuimos llamados a esa paz «en un cuerpo»; no es solo una paz privada, sino la armonía entre los hermanos. Luego cierra con tres palabras sencillas: «y sed agradecidos». La gratitud y la paz caminan juntas. Un corazón agradecido discute menos, se queja menos y perdona más. Al acercarse el final del año, usted puede dejar que la paz y la gratitud sean las que decidan.",
"Paulo descreve a vida nova do crente em comunidade. Depois de falar de perdão e amor, ele diz: «a paz de Cristo… governe em vossos corações». A palavra governar lembra um árbitro que decide num jogo. Quando surgem conflitos, emoções fortes ou decisões difíceis, a paz de Cristo deve ter a última palavra no seu interior. E ele acrescenta que fomos chamados a essa paz «em um só corpo»; não é apenas uma paz particular, mas a harmonia entre os irmãos. Depois termina com três palavras simples: «e sede gratos». A gratidão e a paz andam juntas. Um coração agradecido discute menos, reclama menos e perdoa mais. Ao se aproximar o fim do ano, você pode deixar que a paz e a gratidão sejam as que decidem.",
"Antes de responder hoy en una situación tensa, deténgase y pregunte qué decisión trae la paz de Cristo.",
"Antes de responder hoje numa situação tensa, pare e pergunte qual decisão traz a paz de Cristo.",
"Señor, que la paz de Cristo gobierne mi corazón en cada decisión y en cada conflicto. Dame un espíritu agradecido, que se queje menos y perdone más, y que contribuya a la paz de mi familia y de mi iglesia. En el nombre de Jesús, amén.",
"Senhor, que a paz de Cristo governe meu coração em cada decisão e em cada conflito. Dá-me um espírito agradecido, que reclame menos e perdoe mais, e que contribua para a paz da minha família e da minha igreja. Em nome de Jesus, amém.")

E("47.4.4-5", "En el cumplimiento del tiempo", "Quando o tempo se completou",
"Pablo resume el sentido de la Navidad en pocas palabras. «Venido el cumplimiento del tiempo», es decir, en el momento exacto que Dios había determinado, «Dios envió su Hijo». No fue un accidente ni una improvisación; fue el plan eterno del Padre. Jesús fue «hecho de mujer», verdaderamente humano, y «súbdito a la ley», viviendo en obediencia perfecta. ¿Para qué? «Para que redimiese a los que estaban debajo de la ley», y para que recibiésemos «la adopción de hijos». El pesebre de Belén apunta a la cruz y a la familia de Dios. Cristo se hizo uno de nosotros para que nosotros pudiéramos ser hijos de Dios. En este día, mientras se celebra su nacimiento, usted puede adorar al Hijo que vino a buscarle y a llevarle a casa.",
"Paulo resume o sentido do Natal em poucas palavras. «Quando o tempo se completou», isto é, no momento exato que Deus havia determinado, «Deus enviou o seu Filho». Não foi um acidente nem um improviso; foi o plano eterno do Pai. Jesus nasceu de mulher, verdadeiramente humano, e nasceu sob a Lei, vivendo em obediência perfeita. Para quê? «Para redimir os que estavam sob a Lei», e para que recebêssemos «a adoção como filhos». A manjedoura de Belém aponta para a cruz e para a família de Deus. Cristo se tornou um de nós para que nós pudéssemos ser filhos de Deus. Neste dia, enquanto se celebra o seu nascimento, você pode adorar o Filho que veio buscá-lo e levá-lo para casa.",
"Comparta hoy con su familia, antes de la comida, por qué vino Jesús al mundo.",
"Compartilhe hoje com sua família, antes da refeição, por que Jesus veio ao mundo.",
"Padre, gracias porque en el tiempo exacto enviaste al Hijo al mundo. Gracias, Señor Jesús, por hacerte hombre para redimirme y darme un lugar en la familia de Dios. Recibe hoy mi adoración. En el nombre de Jesús, amén.",
"Pai, obrigado porque no tempo exato enviaste o teu Filho ao mundo. Obrigado, Senhor Jesus, por te fazeres homem para me redimir e me dar um lugar na família de Deus. Recebe hoje a minha adoração. Em nome de Jesus, amém.")

E("51.5.16-18", "Gozo, oración y gratitud", "Alegria, oração e gratidão",
"Estas tres frases cortas parecen sencillas, pero resumen toda una manera de vivir: «estad siempre gozosos. Orad sin cesar. Dad gracias en todo». Note que Pablo no dice «dad gracias por todo», como si el mal fuera bueno, sino «en todo», es decir, en cualquier circunstancia. Aun en medio del dolor podemos reconocer la fidelidad de Dios. Orar sin cesar no significa estar todo el día de rodillas, sino vivir en una conversación constante con Dios. Y el versículo termina con una frase que responde a una pregunta que muchos se hacen: ¿cuál es la voluntad de Dios para mi vida? Aquí hay una parte clara: «esta es la voluntad de Dios para con vosotros en Cristo Jesús». Hoy, al repasar el año, usted puede practicar las tres.",
"Estas três frases curtas parecem simples, mas resumem todo um modo de viver: «alegrai-vos sempre. Orai sem cessar. Agradecei em tudo». Observe que Paulo não diz «agradecei por tudo», como se o mal fosse bom, mas «em tudo», isto é, em qualquer circunstância. Mesmo no meio da dor podemos reconhecer a fidelidade de Deus. Orar sem cessar não significa ficar o dia todo de joelhos, mas viver numa conversa constante com Deus. E o versículo termina com uma frase que responde a uma pergunta que muitos fazem: qual é a vontade de Deus para a minha vida? Aqui há uma parte clara: «essa é a vontade de Deus em Cristo Jesus para vós mesmos». Hoje, ao rever o ano, você pode praticar as três.",
"Escriba una lista de las bendiciones de este año y dé gracias a Dios por cada una.",
"Escreva uma lista das bênçãos deste ano e agradeça a Deus por cada uma.",
"Señor, al mirar este año quiero darte gracias en todo: por las alegrías y también por lo que aprendí en las pruebas. Enséñame a vivir con gozo, a orar sin cesar y a cumplir así la voluntad de Dios. En el nombre de Jesús, amén.",
"Senhor, ao olhar para este ano quero te agradecer em tudo: pelas alegrias e também pelo que aprendi nas provas. Ensina-me a viver com alegria, a orar sem cessar e a cumprir assim a vontade de Deus. Em nome de Jesus, amém.")

E("49.1.6", "Él terminará la obra", "Ele completará a obra",
"Pablo escribe a los filipenses con gratitud por su participación en el evangelio desde el primer día. Y expresa una confianza firme: «el que comenzó en vosotros la buena obra, la perfeccionará hasta el día de Jesucristo». La obra de salvación y transformación en su vida no la comenzó usted, sino Dios. Y lo que Dios comienza, Él lo termina. No abandona proyectos a medias. Al final de un año, es común ver lo que no se cumplió: metas pendientes, hábitos que no cambiaron, oraciones sin respuesta visible. Este versículo nos recuerda que la obra principal no depende del calendario, sino de la fidelidad de Dios. Usted todavía está en construcción, y el Constructor es fiel. Lo que empezó en usted llegará a su plenitud en el día de Cristo.",
"Paulo escreve aos filipenses com gratidão pela participação deles no evangelho desde o primeiro dia. E expressa uma confiança firme: «aquele que começou a boa obra em vós irá completá-la até o dia de Cristo Jesus». A obra de salvação e transformação na sua vida não foi começada por você, mas por Deus. E o que Deus começa, ele termina. Ele não abandona projetos pela metade. No fim de um ano, é comum ver o que não se cumpriu: metas pendentes, hábitos que não mudaram, orações sem resposta visível. Este versículo nos lembra que a obra principal não depende do calendário, mas da fidelidade de Deus. Você ainda está em construção, e o Construtor é fiel. O que ele começou em você chegará à sua plenitude no dia de Cristo.",
"Anote algo que Dios comenzó en usted este año y agradézcale por adelantado por completarlo.",
"Anote algo que Deus começou em você este ano e agradeça a ele antecipadamente por completá-lo.",
"Padre, gracias por la buena obra que comenzaste en mí. Cuando vea lo que todavía falta, ayúdame a confiar en la fidelidad de Dios. Sigue trabajando en mi vida hasta el día de Jesucristo. En el nombre de Jesús, amén.",
"Pai, obrigado pela boa obra que começaste em mim. Quando eu vir o que ainda falta, ajuda-me a confiar na tua fidelidade. Continua trabalhando na minha vida até o dia de Jesus Cristo. Em nome de Jesus, amém.")

E("49.3.13-14", "Olvidar lo que queda atrás", "Esquecer o que ficou para trás",
"Pablo, con toda su experiencia, reconoce humildemente: «no hago cuenta de haberlo ya alcanzado». Pero tiene una sola prioridad: «olvidando ciertamente lo que queda atrás, y extendiéndome a lo que está delante, prosigo al blanco». Olvidar no significa borrar la memoria, sino no dejar que el pasado gobierne el presente. Pablo tenía éxitos religiosos de los que podía jactarse y fracasos graves, como haber perseguido a la iglesia. Ni lo uno ni lo otro debía detenerle. Al terminar el año, usted también tiene logros que pueden volverle orgulloso y heridas o errores que pueden paralizarle. Entrégueselos a Dios. La meta sigue delante: «el premio de la soberana vocación de Dios en Cristo Jesús». Extiéndase hacia lo que Dios tiene por delante.",
"Paulo, com toda a sua experiência, reconhece humildemente: «não considero como se já tivesse a obtido». Mas ele tem uma só prioridade: «esqueço as coisas que ficam para trás, e avanço para as que estão adiante», perseguindo o alvo. Esquecer não significa apagar a memória, mas não deixar que o passado governe o presente. Paulo tinha sucessos religiosos de que poderia se gabar e fracassos graves, como ter perseguido a igreja. Nem um nem outro deveria detê-lo. Ao terminar o ano, você também tem conquistas que podem deixá-lo orgulhoso e feridas ou erros que podem paralisá-lo. Entregue-os a Deus. O alvo continua à frente: «o prêmio do chamado de cima, de Deus em Cristo Jesus». Avance para o que Deus tem adiante.",
"Escriba algo del pasado que necesita soltar y entréguelo hoy a Dios en oración.",
"Escreva algo do passado que você precisa soltar e entregue-o hoje a Deus em oração.",
"Señor, hoy pongo delante de ti lo que queda atrás: mis logros, mis errores y mis heridas. No quiero vivir atado al pasado. Ayúdame a extenderme hacia lo que está delante y a proseguir al blanco en Cristo Jesús. En el nombre de Jesús, amén.",
"Senhor, hoje coloco em tuas mãos o que ficou para trás: minhas conquistas, meus erros e minhas feridas. Não quero viver preso ao passado. Ajuda-me a avançar para o que está adiante e a prosseguir para o alvo em Cristo Jesus. Em nome de Jesus, amém.")

E("57.13.8", "El mismo ayer y hoy", "O mesmo ontem e hoje",
"El autor de Hebreos acaba de pedir que recordemos a los pastores que nos enseñaron la Palabra y que imitemos su fe. Los líderes pasan, las generaciones cambian, pero hay Uno que permanece: «Jesucristo es el mismo ayer, y hoy, y por los siglos». El Cristo que perdonó, sanó y salvó en los Evangelios es el mismo hoy. El que fue fiel con usted en el año que termina será fiel en el que comienza. Por eso el versículo siguiente advierte que no nos dejemos llevar por doctrinas diversas y extrañas. En un mundo donde todo cambia con rapidez, el creyente tiene un ancla firme. Usted no sabe qué traerá el nuevo año, pero sabe quién estará allí. Y Él no cambia.",
"O autor de Hebreus acaba de pedir que nos lembremos dos pastores que nos ensinaram a Palavra e que imitemos a fé deles. Os líderes passam, as gerações mudam, mas há Um que permanece: «Jesus Cristo é o mesmo ontem, hoje, e eternamente». O Cristo que perdoou, curou e salvou nos Evangelhos é o mesmo hoje. Aquele que foi fiel a você no ano que termina será fiel no ano que começa. Por isso o versículo seguinte adverte que não nos deixemos levar por doutrinas várias e estranhas. Num mundo onde tudo muda com rapidez, o crente tem uma âncora firme. Você não sabe o que o novo ano trará, mas sabe quem estará lá. E ele não muda.",
"Recuerde una fidelidad concreta de Cristo en este año y confíele, en oración, los planes del próximo.",
"Lembre-se de uma fidelidade concreta de Cristo neste ano e confie a ele, em oração, os planos do próximo.",
"Señor Jesús, gracias porque eres el mismo ayer, hoy y por los siglos. Fuiste fiel conmigo en este año y confío en que lo serás en el próximo. Guárdame firme en la verdad, en medio de un mundo que cambia. En el nombre de Jesús, amén.",
"Senhor Jesus, obrigado porque és o mesmo ontem, hoje e eternamente. Foste fiel comigo neste ano e confio que serás no próximo. Guarda-me firme na verdade, no meio de um mundo que muda. Em nome de Jesus, amém.")

E("65.22.20", "Ven, Señor Jesús", "Vem, Senhor Jesus",
"Estas son casi las últimas palabras de toda la Biblia. El Señor Jesús, que da testimonio de todas estas cosas, afirma: «Ciertamente, vengo en breve». Y la respuesta de la iglesia es una oración: «Amén, sea así. Ven, Señor Jesús». La Biblia termina no con un punto final, sino con una espera llena de anhelo. La iglesia primitiva oraba así, y los creyentes de todas las épocas han repetido esta oración. Esperar a Cristo no es mirar al cielo con los brazos cruzados, sino vivir cada día preparados, sirviendo y anunciando el evangelio. Al final de este año, usted puede unir su voz a la de la iglesia de todos los tiempos. Lo que viene por delante es incierto, pero el final de la historia ya está escrito: Él viene.",
"Estas são quase as últimas palavras de toda a Bíblia. O Senhor Jesus, que dá testemunho de todas estas coisas, afirma: «Certamente logo venho». E a resposta da igreja é uma oração: «Amém! Sim, vem, Senhor Jesus!». A Bíblia termina não com um ponto final, mas com uma espera cheia de anseio. A igreja primitiva orava assim, e os crentes de todas as épocas repetiram essa oração. Esperar Cristo não é olhar para o céu de braços cruzados, mas viver cada dia preparado, servindo e anunciando o evangelho. No fim deste ano, você pode unir a sua voz à da igreja de todos os tempos. O que vem pela frente é incerto, mas o fim da história já está escrito: ele vem.",
"Termine hoy su oración con las palabras «Ven, Señor Jesús», examinando si su vida está preparada.",
"Termine hoje a sua oração com as palavras «Vem, Senhor Jesus», examinando se a sua vida está preparada.",
"Señor Jesús, creo en la promesa de que vendrás. Mientras espero, ayúdame a vivir preparado, sirviendo con fidelidad y anunciando el evangelio. Mi corazón dice con toda la iglesia: Amén, ven, Señor Jesús. En el nombre de Jesús, amén.",
"Senhor Jesus, creio na promessa da tua vinda. Enquanto espero, ajuda-me a viver preparado, servindo com fidelidade e anunciando o evangelho. Meu coração diz com toda a igreja: Amém, vem, Senhor Jesus. Em nome de Jesus, amém.")

E("65.21.5", "Todas las cosas nuevas", "Todas as coisas novas",
"Desde el trono, Dios mismo habla y declara: «He aquí, yo hago nuevas todas las cosas». No dice «haré cosas nuevas», como si añadiera algo más a lo viejo, sino que hace nuevas todas las cosas. Su propósito es restaurar por completo lo que el pecado dañó. Y para que no quede duda, ordena a Juan: «Escribe; porque estas palabras son fieles y verdaderas». La promesa está garantizada por el carácter de Dios. En el último día del año, mientras muchos hablan de comienzos nuevos con buenos propósitos, el creyente tiene algo más firme que un deseo: una promesa de Dios. Lo que Él comenzó en usted por medio de Cristo, lo llevará a su plenitud en la nueva creación. Puede entrar al nuevo año con esperanza segura.",
"Do trono, o próprio Deus fala e declara: «Eis que eu faço novas todas as coisas». Ele não diz «farei coisas novas», como se acrescentasse algo ao velho, mas que faz novas todas as coisas. O seu propósito é restaurar por completo o que o pecado estragou. E, para que não reste dúvida, ele ordena a João: «Escreve, porque estas palavras são verdadeiras e fiéis». A promessa está garantida pelo caráter de Deus. No último dia do ano, enquanto muitos falam de recomeços com boas intenções, o crente tem algo mais firme do que um desejo: uma promessa de Deus. O que ele começou em você por meio de Cristo, ele levará à plenitude na nova criação. Você pode entrar no novo ano com esperança segura.",
"Entregue hoy a Dios el año que comienza y escriba este versículo como lema para los próximos meses.",
"Entregue hoje a Deus o ano que começa e escreva este versículo como lema para os próximos meses.",
"Señor, gracias por acompañarme todo este año. Hoy pongo delante de ti el año que comienza. Creo en la promesa de que haces nuevas todas las cosas. Renueva mi corazón, mi familia y mi iglesia, y guíame cada día. En el nombre de Jesús, amén.",
"Senhor, obrigado por me acompanhar durante todo este ano. Hoje coloco em tuas mãos o ano que começa. Creio na promessa de que fazes novas todas as coisas. Renova meu coração, minha família e minha igreja, e guia-me cada dia. Em nome de Jesus, amém.")


# --- Validação ---
def palavras(s):
    return len(re.findall(r"[0-9A-Za-zÀ-ÿ]+(?:[-'][0-9A-Za-zÀ-ÿ]+)*", s))


def main():
    pt = json.load(open(os.path.join(RAIZ, "app/biblia/pt-livre.json"), encoding="utf-8"))
    es = json.load(open(os.path.join(RAIZ, "app/biblia/es-rv1909.json"), encoding="utf-8"))
    erros = []
    esperado = ULTIMO_DIA - PRIMEIRO_DIA + 1
    if len(D) != esperado:
        erros.append("total %d, esperado %d" % (len(D), esperado))
    vistos = {}
    proib_es = re.compile(r"\b(tú|tu|tus|tienes|puedes)\b", re.I)
    # no texto dirigido ao leitor (reflexão e "para hoy") também não pode haver formas de "tú"
    proib_leitor = re.compile(r"\b(te|ti|contigo|eres|estás|haces|sabes|quieres)\b", re.I)
    for i, d in enumerate(D):
        dia = PRIMEIRO_DIA + i
        tag = "dia %d (%s)" % (dia, d.get("v"))
        m = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)(?:-(\d+))?", d["v"])
        if not m:
            erros.append(tag + ": ref mal formada"); continue
        b, c, v1 = int(m[1]), int(m[2]), int(m[3])
        v2 = int(m[4]) if m[4] else v1
        if not 44 <= b <= 65:
            erros.append(tag + ": livro fora de Romanos-Apocalipse")
        if not (v1 <= v2 and v2 - v1 <= 2):
            erros.append(tag + ": intervalo deve ter 1 a 3 versículos")
        for nome, bib in (("pt-livre", pt), ("es-rv1909", es)):
            try:
                cap = bib[b][c - 1]
                if c < 1 or v1 < 1 or v2 > len(cap) or not all(cap[x - 1].strip() for x in range(v1, v2 + 1)):
                    raise IndexError
            except IndexError:
                erros.append("%s: ref inexistente em %s" % (tag, nome))
        if d["v"] in vistos:
            erros.append("%s: ref repetida (dia %d)" % (tag, vistos[d["v"]]))
        vistos[d["v"]] = dia
        for k in ("t", "r", "a", "o"):
            if not (isinstance(d[k], list) and len(d[k]) == 2 and all(isinstance(s, str) and s.strip() for s in d[k])):
                erros.append(tag + ": campo %s precisa ser [ES, PT]" % k)
        for lang, j in (("ES", 0), ("PT", 1)):
            n = palavras(d["t"][j])
            if not 2 <= n <= 6:
                erros.append("%s: título %s com %d palavras" % (tag, lang, n))
            n = palavras(d["r"][j])
            if not 90 <= n <= 140:
                erros.append("%s: reflexão %s com %d palavras" % (tag, lang, n))
            n = palavras(d["o"][j])
            if not 30 <= n <= 60:
                erros.append("%s: oração %s com %d palavras" % (tag, lang, n))
            if d["a"][j].count(".") > 1 or not d["a"][j].endswith("."):
                erros.append("%s: 'para hoje' %s deve ser uma frase" % (tag, lang))
        if not d["o"][0].startswith("Señor") and not d["o"][0].startswith(("Padre", "Espíritu", "Dios")):
            erros.append(tag + ": oração ES deve começar invocando a Deus")
        if not d["o"][0].endswith("En el nombre de Jesús, amén."):
            erros.append(tag + ": oração ES sem o final padrão")
        if not d["o"][1].endswith("Em nome de Jesus, amém."):
            erros.append(tag + ": oração PT sem o final padrão")
        for k in ("t", "r", "a", "o"):
            if proib_es.search(d[k][0]):
                erros.append("%s: forma de 'tú' em %s ES: %r" % (tag, k, proib_es.search(d[k][0])[0]))
        for k in ("r", "a"):
            if proib_leitor.search(d[k][0]):
                erros.append("%s: forma de 'tú' em %s ES: %r" % (tag, k, proib_leitor.search(d[k][0])[0]))
        tudo = json.dumps(d, ensure_ascii=False)
        if re.search("[\U0001F300-\U0001FAFF☀-➿]", tudo):
            erros.append(tag + ": contém emoji")
    if erros:
        print("\n".join(erros))
        print("%d erro(s); JSON não gravado." % len(erros))
        sys.exit(1)
    with open(SAIDA, "w", encoding="utf-8") as f:
        json.dump(D, f, ensure_ascii=False, separators=(",", ":"))
    print("OK: %d devocionais (dias %d-%d) gravados em %s" % (len(D), PRIMEIRO_DIA, ULTIMO_DIA, SAIDA))


if __name__ == "__main__":
    main()
